// Clean the form data and normalise the phone. The phone function is the same one as
// n8n/snippets/normalize-phone.js (rule 7) - keep them identical.
// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
  const cc = (typeof $env !== 'undefined' && $env && /^[1-9]\d{0,2}$/.test(String($env.FLOWHQ_DEFAULT_COUNTRY_CODE || ''))) ? String($env.FLOWHQ_DEFAULT_COUNTRY_CODE) : '91';
  let digits = s.replace(/\D/g, '');
  if (s.startsWith('00')) digits = digits.slice(2);
  else if (!s.startsWith('+')) {                                  // written locally
    if (cc === '91') { if (!(digits.length === 12 && digits.startsWith('91'))) { if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1); digits = `91${digits}`; } }
    else digits = `${cc}${digits.replace(/^0+/, '')}`;
  }
  let valid = /^[1-9]\d{7,14}$/.test(digits);
  if (valid && digits.startsWith('91')) valid = /^91[6-9]\d{9}$/.test(digits);   // +91 numbers are Indian mobiles
  return { phone: valid ? `+${digits}` : null, valid };
}

const body = $json.body || {};
const noControl = (v) => String(v === null || v === undefined ? '' : v).replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '');
const line = (v, max) => noControl(v).replace(/\s+/g, ' ').trim().slice(0, max);
const text = (v, max) => noControl(v).trim().slice(0, max);

const slug = line(body.clinic_slug, 40).toLowerCase();
const clinic_slug = /^[a-z0-9-]{2,40}$/.test(slug) ? slug : '';
const name = line(body.name, 100);
const { phone, valid } = normalizeIndianPhone(body.phone);
const honeypot = line(body.website, 200);   // hidden field: humans leave it empty, bots fill it
const yes = (v) => v === true || ['true', 'on', 'yes', '1'].includes(String(v === null || v === undefined ? '' : v).trim().toLowerCase());
const emailRaw = line(body.email, 120);
const email = /^[^\s@<>"']{1,64}@[^\s@<>"']+\.[A-Za-z]{2,}$/.test(emailRaw) ? emailRaw.toLowerCase() : '';
const consent_whatsapp = yes(body.consent_whatsapp) || yes(body.consent);   // the form's consent checkbox (HTML sends "on")
const consent_email = yes(body.consent_email) && !!email;
const consent_version = line(body.consent_version, 40);                     // which consent text the person saw

let skip_reason = '';
if (honeypot) skip_reason = 'honeypot filled';
else if (!name) skip_reason = 'missing name';
else if (!valid) skip_reason = 'invalid phone';
else if (emailRaw && !email) skip_reason = 'invalid email';
else if ($json.require_consent !== false && !consent_whatsapp) skip_reason = 'consent required';

return {
  json: {
    grist_base_url: String($json.grist_base_url || '').replace(/\/+$/, ''),
    registry_doc_id: String($json.registry_doc_id || '').trim(),
    clinic_slug,
    name,
    phone,
    phone_raw: line(body.phone, 30),
    enquiry: text(body.enquiry, 1000),
    page_url: line(body.page_url, 500),
    utm_campaign: line(body.utm_campaign, 100),
    email,
    consent_whatsapp,
    consent_email,
    consent_version,
    input_ok: skip_reason === '',
    skip_reason,
  },
};

const ctx = $('W1 – Prepare lead').first().json;
const rec = ($json.records || [])[0];
const f = rec ? rec.fields || {} : {};
const found = !!(
rec &&
ctx.clinic_slug &&
f.Clinic_Slug === ctx.clinic_slug &&
(f.Active === true || f.Active === 1 || String(f.Active).toLowerCase() === 'true') &&
f.Grist_Doc_ID
);
return {
  json: {
    ...ctx,
    clinic_found: found,
    doc_id: found ? String(f.Grist_Doc_ID).trim() : '',
    clinic_name: found ? String(f.Clinic_Name || '') : '',
    wa_phone_number_id: found ? String(f.WA_Phone_Number_ID || '') : '',
  },
};

const ctx = $('W1 – Resolve clinic').first().json;
const rec = $json.records[0];
const old = String(rec.fields.Enquiry || '');
const today = new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 10);   // IST date

const fields = {};
if (ctx.enquiry && !old.includes(ctx.enquiry)) {
  fields.Enquiry = old ? `${old}\n---\n${today}: ${ctx.enquiry}` : ctx.enquiry;
}
if (ctx.page_url && ctx.page_url !== String(rec.fields.Page_URL || '')) fields.Page_URL =    ctx.page_url;
if (ctx.utm_campaign && ctx.utm_campaign !== String(rec.fields.UTM_Campaign || ''))    fields.UTM_Campaign = ctx.utm_campaign;

// consent given NOW is recorded; earlier consent is never removed here
if (ctx.consent_whatsapp && !rec.fields.Consent_WhatsApp) { fields.Consent_WhatsApp = true; fields.Consent_Source = 'website-form'; fields.Consent_At = Math.floor(Date.now() / 1000); if (ctx.consent_version) fields.Consent_Version = ctx.consent_version; }
if (ctx.consent_email && !rec.fields.Consent_Email) fields.Consent_Email = true;
if (ctx.email && !String(rec.fields.Email || '')) fields.Email = ctx.email;

const has_changes = Object.keys(fields).length > 0;
return {
  json: {
    ...ctx,
    action: 'updated',
    lead_id: rec.fields.Lead_id || rec.fields.Lead_ID || `row ${rec.id}`,
    lead_row_id: rec.id,
    has_changes,
    skip_reason: has_changes ? '' : 'duplicate submission',
    patch: { records: [{ id: rec.id, fields }] },
  },
};

const ctx = $('W1 – Resolve clinic').first().json;
const now = Date.now();
const ymd = new Date(now + 5.5 * 3600 * 1000).toISOString().slice(0, 10).replace(/-/g, '');   // IST date
const prefix = `L-${ymd}-`;

let max = 0;
for (const r of $json.records || []) {
  const id = String((r.fields || {}).Lead_id || '');
  if (id.startsWith(prefix)) max = Math.max(max, parseInt(id.slice(prefix.length), 10) || 0);
}
const lead_id = prefix + String(max + 1).padStart(4, '0');

const fields = {
  Lead_id: lead_id,
  Created_At: Math.floor(now / 1000),   // Grist DateTime = epoch seconds
  Name: ctx.name,
  Phone: ctx.phone,
  Source: 'Website',
  Page_URL: ctx.page_url,
  UTM_Campaign: ctx.utm_campaign,
  Enquiry: ctx.enquiry,
  Status: 'New',
  Email: ctx.email,
  Email_Opted_Out: false,
  Consent_WhatsApp: ctx.consent_whatsapp === true,
  Consent_Email: ctx.consent_email === true,
  Consent_Source: ctx.consent_whatsapp ? 'website-form' : 'website-form (no consent given)',
  Consent_At: ctx.consent_whatsapp ? Math.floor(now / 1000) : null,
  Consent_Version: ctx.consent_version,
};
return { json: { ...ctx, action: 'created', lead_id, create: { records: [{ fields }] } } };   // lead_row_id is known after the insert

return {
  json: {
    ...$json,
    log: {
      Workflow: 'W1-website-lead',
      Record: $json.phone || $json.phone_raw || '',
      Outcome: 'skipped',
      Error: $json.skip_reason || 'unknown',
      At: Math.floor(Date.now() / 1000),
    },
  },
};

const cfg = $('W3 – Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');

const clinics = ($input.first().json.records || []).filter(
  (r) =>
    r.fields &&
    String(r.fields.Active).toUpperCase() === 'TRUE' &&
    String(r.fields.Grist_Doc_ID || '').trim()
);

return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
    wa_phone_number_id: String(r.fields.WA_Phone_Number_ID || '').trim(),
  },
  pairedItem: { item: 0 },
}));

// Pasted from n8n/snippets/clinic-hours.js - keep identical.
const DAY_INDEX = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };

function parseClock(text) {
  const m = String(text === null || text === undefined ? '' : text).trim().match(/^(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?$/i);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const meridiem = m[3] ? m[3][0].toLowerCase() : '';
  if (min > 59) return null;
  if (meridiem) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (meridiem === 'p' ? 12 : 0);
  } else if (h > 24 || (h === 24 && min > 0)) {
    return null;
  }
  return h * 60 + min;   // minutes after midnight
}

function parseDays(text) {
  const s = String(text === null || text === undefined ? '' : text).toLowerCase().replace(/[–—]/g, '-').replace(/\s+to\s+/g, '-').replace(/\s+(and|&)\s+/g, ',').trim();
  if (!s) return null;
  if (/^(daily|every ?day|all days|7 ?days?)$/.test(s)) return [0, 1, 2, 3, 4, 5, 6];
  const dayOf = (t) => {
    const x = t.trim();
    return /^(sun|mon|tue|wed|thu|fri|sat)[a-z]*\.?$/.test(x) ? DAY_INDEX[x.slice(0, 3)] : undefined;
  };
  const days = new Set();
  for (const token of s.split(/[,;/]+/)) {
    if (!token.trim()) continue;
    if (token.includes('-')) {
      const [a, b] = token.split('-').map(dayOf);
      if (a === undefined || b === undefined) return null;
      for (let d = a; ; d = (d + 1) % 7) { days.add(d); if (d === b) break; }
    } else {
      const d = dayOf(token);
      if (d === undefined) return null;
      days.add(d);
    }
  }
  return days.size ? [...days].sort() : null;   // 0 = Sunday
}

function isOpenNow(i) {
  if (!Number.isFinite(i.now_ms)) return { open: false, source: 'default' };
  let open = parseClock(i.open_time);
  let close = parseClock(i.close_time);
  let days = parseDays(i.working_days);
  let source = 'settings';
  if (open === null || close === null || close <= open) { open = 8 * 60; close = 21 * 60; source = 'default'; }
  if (days === null) { days = [0, 1, 2, 3, 4, 5, 6]; source = 'default'; }
  const t = new Date(i.now_ms + 5.5 * 3600 * 1000);   // IST wall-clock via UTC getters
  const minutes = t.getUTCHours() * 60 + t.getUTCMinutes();
  return { open: days.includes(t.getUTCDay()) && minutes >= open && minutes < close, source };
}

  const clinics = $('W3 – Split clinics').all();
  return $input.all().map((item, i) => {
    const s = {};
    for (const r of item.json.records || []) {
      const f = r.fields || {};
      if (f.Key) s[String(f.Key).trim()] = f.Value;
    }
    const hours = isOpenNow({ open_time: s.open_time, close_time: s.close_time, working_days: s.working_days, now_ms: Date.now() });
    return {
      json: {
        ...clinics[i].json,
        clinic_name: String(s.clinic_name || clinics[i].json.registry_clinic_name || ''),
        owner_phone: s.owner_phone,
        test_mode: s.TEST_MODE,         // raw text; a missing row means TEST_MODE is ON (see send-guard.js)
        test_phone: s.TEST_PHONE,
        open_now: hours.open,
        hours_source: hours.source,      // 'default' = open_time / close_time / working_days missing or unreadable
      },
      pairedItem: { item: i },
    };
  });

// Pasted from n8n/snippets/lead-context.js - keep identical.
const LC_STAGE_RANK = { hot: 0, warm: 1, cold: 2 };
const LC_DONE_INTENTS = ['not_interested', 'opt_out'];
const LC_CHANGE_INTENTS = ['cancel_appointment', 'reschedule_appointment'];
const LC_RECENT_MIN = 48 * 60;   // W6: the patient wrote in the last 48 h = the conversation is live
const LC_ACTIVE_MIN = 60;        // W3: wrote in the last hour = reply now
const LC_REQUEST_MIN = 24 * 60;  // W5: a cancel / reschedule request older than this no longer holds a reminder

function lcText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function lcSec(v) { const n = typeof v === 'number' ? v : NaN; return Number.isFinite(n) && n > 0 ? n : null; }   // Grist DateTime = seconds
function lcAgo(min) { return min < 60 ? `${min} min ago` : min < 48 * 60 ? `${Math.round(min / 60)} h ago` : `${Math.round(min / 1440)} days ago`; }

// Conversations rows -> { [lead row id]: compact state }. Several conversations for one lead are merged (any Needs_Human /
// Automation_Paused counts; the newest inbound decides Last_Intent and Handoff_Reason).
function lcConversations(records) {
  const byLead = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const lead = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const c = byLead[lead] || (byLead[lead] = { needs_human: false, paused: false, assigned_to: '', last_inbound_at: null, last_intent: '', handoff_note: '' });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned_to) c.assigned_to = lcText(f.Assigned_To, 60);
    const at = lcSec(f.Last_Inbound_At);
    const newer = at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at);
    if (newer || (c.last_inbound_at === null && !c.last_intent)) {
      if (at !== null) c.last_inbound_at = at;
      c.last_intent = lcText(f.Last_Intent, 40);
      c.handoff_note = lcText(f.Handoff_Reason, 160);
    }
  }
  return byLead;
}

// One lead (Grist row) + its conversation state -> the compact context the workflows use.
function leadContext(lead, conv, nowMs) {
  const f = (lead && lead.fields) || {};
  const c = conv || null;
  const stage = Object.prototype.hasOwnProperty.call(LC_STAGE_RANK, f.Lead_Stage) ? f.Lead_Stage : '';
  const next = lcSec(f.Next_Action_At);
  const inbound = c ? c.last_inbound_at : null;
  return {
    stage,
    rank: stage ? LC_STAGE_RANK[stage] : 1,                  // unknown ranks with warm: no AI data = no change in order
    summary: lcText(f.AI_Summary, 200),
    service: lcText(f.Likely_Service, 80),
    enquiry: lcText(f.Enquiry, 200),
    last_intent: c ? c.last_intent : '',
    handoff_note: c ? c.handoff_note : '',
    last_inbound_at: inbound,
    minutes_since_inbound: inbound !== null ? Math.max(0, Math.floor((nowMs / 1000 - inbound) / 60)) : null,
    next_action_at: next,
    next_action_future: next !== null && next * 1000 > nowMs,
    needs_human: !!(c && c.needs_human),
    paused: !!(c && c.paused),
    assigned_to: c ? c.assigned_to : '',
    opted_out: f.Opted_Out === true,
  };
}

// purpose: 'escalation' (W3 staff alert), 'reminder' (W5, o.kind = r24 | r2), 'followup' (W6 day 2), 'rebook' (W6 no-show,
// o.since = the missed appointment's Start). -> { action, allowed, reason }. allowed = false holds the step back.
function nextBestAction(x, purpose, o = {}) {
  const act = (action, allowed, reason) => ({ action, allowed, reason });
  const wrote = x.minutes_since_inbound;
  const owner = x.assigned_to ? `assigned to ${x.assigned_to}` : 'automation paused';
  const done = x.last_intent === 'opt_out' ? 'the patient asked us to stop' : 'the patient said they are not interested';
  const planned = () => `next contact planned for ${new Date(x.next_action_at * 1000 + 5.5 * 3600 * 1000).toISOString().slice(0, 10)}`;

  if (purpose === 'reminder') {   // reminders stay transactional: only a pending cancel / reschedule request holds the 24 h one
    if (o.kind === 'r24' && x.needs_human && LC_CHANGE_INTENTS.includes(x.last_intent) && wrote !== null && wrote < LC_REQUEST_MIN) {
      return act('human_handoff', false, `24 h reminder held: the patient asked to ${x.last_intent === 'cancel_appointment' ? 'cancel' : 'reschedule'} on WhatsApp ${lcAgo(wrote)} and staff have not answered yet`);
    }
    return act('appointment_reminder', true, 'reminder due');
  }
  if (purpose === 'escalation') {
    if (x.paused || x.assigned_to) return act('wait', false, `staff own this conversation (${owner})`);
    if (x.opted_out) return act('no_action', false, 'the patient opted out');
    if (LC_DONE_INTENTS.includes(x.last_intent)) return act('no_action', false, done);
    if (x.next_action_future) return act('wait', false, planned());
    if (x.needs_human) return act('human_handoff', true, `AI hand-off: ${x.handoff_note || 'see the Grist inbox'}`);
    if (wrote !== null && wrote <= LC_ACTIVE_MIN) return act('reply_now', true, 'reply on WhatsApp now, the patient is active');
    if (x.stage === 'hot') return act('reply_now', true, 'call now, ready to book');
    return act('follow_up', true, 'call or message today');
  }
  if (purpose === 'followup' || purpose === 'rebook') {   // opted out / paused: still stopped later by W6 – Decide send, as before
    if (x.needs_human) return act('human_handoff', false, 'waiting for a person (Needs_Human)');
    if (x.assigned_to) return act('wait', false, `staff own this conversation (${owner})`);
    if (LC_DONE_INTENTS.includes(x.last_intent)) return act('no_action', false, done);
    if (x.next_action_future) return act('wait', false, planned());
    if (purpose === 'rebook') {
      if (x.last_inbound_at !== null && Number.isFinite(o.since) && x.last_inbound_at > o.since) return act('wait', false, 'the patient has written since the missed appointment');
      return act('rebook', true, 'no-show: offer a new time');
    }
    if (wrote !== null && wrote < LC_RECENT_MIN) return act('wait', false, `the patient wrote ${lcAgo(wrote)}`);
    if (x.stage === 'cold') return act('nurture', false, 'the AI rated this lead cold: no day-2 push');
    return act('follow_up', true, x.stage === 'hot' ? 'hot lead: day-2 follow-up first' : 'day-2 follow-up');
  }
  throw new Error(`nextBestAction: unknown purpose ${purpose}`);
}

// W3: what staff need in one look. WHO (name, phone), WHAT (AI summary or enquiry, likely service), RECENT (last intent, when),
// HOW HOT (stage, waiting time), NEXT (the action). brief = the template's "enquiry" value; text = message_text.
function lcStaffBrief(x, nba, o) {
  const tag = x.stage ? `[${x.stage.toUpperCase()}] ` : '';
  const what = (x.summary || x.enquiry || 'no details yet').replace(/[.\s]+$/, '');
  const service = x.service ? ` (${x.service})` : '';
  const recent = [x.last_intent ? x.last_intent.replace(/_/g, ' ') : '', x.minutes_since_inbound !== null ? `wrote ${lcAgo(x.minutes_since_inbound)}` : ''].filter(Boolean).join(', ');
  const tail = `${recent ? ` Last: ${recent}.` : ''} Next: ${nba.reason.replace(/[.\s]+$/, '')}.`;
  return {
    brief: lcText(`${tag}${what}${service}.${tail}`, 240),
    text: lcText(`New lead ${tag}${o.name} (${o.phone}) for ${o.clinic}, waiting ${o.waiting_minutes} min. ${what}${service}.${tail}`, 500),
  };
}

  const cfg = $('W3 – Config').first().json;
  const nowMs = Date.now();
  const minAge = Number(cfg.new_for_minutes);           // waiting at least this long ...
  const maxAge = Number(cfg.max_age_hours) * 60;        // ... but not an old backlog
  const cap = Number(cfg.max_alerts_per_run);           // per clinic per run
  const clinics = $('W3 – Add settings').all();
  const leadsPerClinic = $('W3 – Leads').all();         // one LEADS answer per clinic (this node's input is W3 – Conversations)
  const out = [];

  $input.all().forEach((convs, i) => {
    const item = leadsPerClinic[i] || { json: {} };
    const base = clinics[i].json;
    // What W13 and staff wrote to Conversations (unreadable -> nothing known -> W3 escalates exactly as before).
    const conversations = lcConversations((convs.json && convs.json.records) || []);
    // if (!base.open_now) return;                         // outside clinic hours: leave everything for the next run

    const due = (item.json.records || [])
      .filter((r) => {                                      // the W3 rule, unchanged: New, not escalated, waiting minAge..maxAge
        const f = r.fields || {};
        if (f.Status !== 'New' || f.Escalated || typeof f.Created_At !== 'number') return false;
        const minutes = (nowMs - f.Created_At * 1000) / 60000;
        return minutes >= minAge && minutes <= maxAge;
      })
      .map((r) => {
        const x = leadContext(r, conversations[String(r.id)], nowMs);
        return { r, x, nba: nextBestAction(x, 'escalation') };
      })
      // Held back: staff own the conversation (Automation_Paused / Assigned_To), opted out, said not interested / stop, or a next
      // contact is already planned (Next_Action_At in the future). A lead the AI handed off is skipped through Escalated (set by
      // W13 only when its staff alert was delivered); a failed alert = still escalated here, with the AI's note.
      .filter((d) => d.nba.allowed)
      .sort((a, b) => a.x.rank - b.x.rank || a.r.fields.Created_At - b.r.fields.Created_At)   // hot, warm / unknown, cold; then oldest
      .slice(0, cap);

    for (const { r, x, nba } of due) {
      const f = r.fields;
      const waiting = Math.floor((nowMs - f.Created_At * 1000) / 60000);
      const brief = lcStaffBrief(x, nba, { name: String(f.Name || 'New lead'), phone: String(f.Phone || ''), clinic: base.clinic_name || 'Clinic', waiting_minutes: waiting });
      out.push({
        json: {
          ...base,
          lead_row_id: r.id,
          lead_id: f.Lead_id || `row ${r.id}`,
          lead_name: String(f.Name || ''),
          lead_phone: String(f.Phone || ''),
          source: String(f.Source || ''),
          enquiry: String(f.Enquiry || '').replace(/\s+/g, ' ').trim().slice(0, 200),
          waiting_minutes: waiting,
          escalated: !!f.Escalated,
          lead_stage: x.stage,
          ai_summary: x.summary,
          next_best_action: nba.action,
          staff_brief: brief.brief,                         // -> the template's "enquiry" value
          staff_text: brief.text,                           // -> message_text
        },
        pairedItem: { item: i },
      });
    }
  });
  return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
