// Pasted from n8n/snippets/lead-context.js - keep identical.
const LC_STAGE_RANK = { hot: 0, warm: 1, cold: 2 };
const LC_DONE_INTENTS = ['not_interested', 'opt_out'];
const LC_CHANGE_INTENTS = ['cancel_appointment', 'reschedule_appointment'];
const LC_RECENT_MIN = 48 * 60;   // W6: the patient wrote in the last 48 h = the conversation is live
const LC_ACTIVE_MIN = 60;        // W3: wrote in the last hour = reply now
const LC_REQUEST_MIN = 24 * 60;  // W5: a cancel / reschedule request older than this no longer holds a reminder

function lcText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function lcSec(v) { const n = typeof v === 'number' ? v : NaN; return Number.isFinite(n) && n > 0 ? n : null; }   // Grist DateTime = seconds
function lcAgo(min) { return min < 60 ? `${min} min ago` : min < 48 * 60 ? `${Math.round(min / 60)} h ago` : `${Math.round(min / 1440)} days ago`; }

// Conversations rows -> { [lead row id]: compact state }. Several conversations for one lead are merged (any Needs_Human /
// Automation_Paused counts; the newest inbound decides Last_Intent and Handoff_Reason).
function lcConversations(records) {
  const byLead = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const lead = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const c = byLead[lead] || (byLead[lead] = { needs_human: false, paused: false, assigned_to: '', last_inbound_at: null, last_intent: '', handoff_note: '' });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned_to) c.assigned_to = lcText(f.Assigned_To, 60);
    const at = lcSec(f.Last_Inbound_At);
    const newer = at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at);
    if (newer || (c.last_inbound_at === null && !c.last_intent)) {
      if (at !== null) c.last_inbound_at = at;
      c.last_intent = lcText(f.Last_Intent, 40);
      c.handoff_note = lcText(f.Handoff_Reason, 160);
    }
  }
  return byLead;
}

// One lead (Grist row) + its conversation state -> the compact context the workflows use.
function leadContext(lead, conv, nowMs) {
  const f = (lead && lead.fields) || {};
  const c = conv || null;
  const stage = Object.prototype.hasOwnProperty.call(LC_STAGE_RANK, f.Lead_Stage) ? f.Lead_Stage : '';
  const next = lcSec(f.Next_Action_At);
  const inbound = c ? c.last_inbound_at : null;
  return {
    stage,
    rank: stage ? LC_STAGE_RANK[stage] : 1,                  // unknown ranks with warm: no AI data = no change in order
    summary: lcText(f.AI_Summary, 200),
    service: lcText(f.Likely_Service, 80),
    enquiry: lcText(f.Enquiry, 200),
    last_intent: c ? c.last_intent : '',
    handoff_note: c ? c.handoff_note : '',
    last_inbound_at: inbound,
    minutes_since_inbound: inbound !== null ? Math.max(0, Math.floor((nowMs / 1000 - inbound) / 60)) : null,
    next_action_at: next,
    next_action_future: next !== null && next * 1000 > nowMs,
    needs_human: !!(c && c.needs_human),
    paused: !!(c && c.paused),
    assigned_to: c ? c.assigned_to : '',
    opted_out: f.Opted_Out === true,
  };
}

// purpose: 'escalation' (W3 staff alert), 'reminder' (W5, o.kind = r24 | r2), 'followup' (W6 day 2), 'rebook' (W6 no-show,
// o.since = the missed appointment's Start). -> { action, allowed, reason }. allowed = false holds the step back.
function nextBestAction(x, purpose, o = {}) {
  const act = (action, allowed, reason) => ({ action, allowed, reason });
  const wrote = x.minutes_since_inbound;
  const owner = x.assigned_to ? `assigned to ${x.assigned_to}` : 'automation paused';
  const done = x.last_intent === 'opt_out' ? 'the patient asked us to stop' : 'the patient said they are not interested';
  const planned = () => `next contact planned for ${new Date(x.next_action_at * 1000 + 5.5 * 3600 * 1000).toISOString().slice(0, 10)}`;

  if (purpose === 'reminder') {   // reminders stay transactional: only a pending cancel / reschedule request holds the 24 h one
    if (o.kind === 'r24' && x.needs_human && LC_CHANGE_INTENTS.includes(x.last_intent) && wrote !== null && wrote < LC_REQUEST_MIN) {
      return act('human_handoff', false, `24 h reminder held: the patient asked to ${x.last_intent === 'cancel_appointment' ? 'cancel' : 'reschedule'} on WhatsApp ${lcAgo(wrote)} and staff have not answered yet`);
    }
    return act('appointment_reminder', true, 'reminder due');
  }
  if (purpose === 'escalation') {
    if (x.paused || x.assigned_to) return act('wait', false, `staff own this conversation (${owner})`);
    if (x.opted_out) return act('no_action', false, 'the patient opted out');
    if (LC_DONE_INTENTS.includes(x.last_intent)) return act('no_action', false, done);
    if (x.next_action_future) return act('wait', false, planned());
    if (x.needs_human) return act('human_handoff', true, `AI hand-off: ${x.handoff_note || 'see the Grist inbox'}`);
    if (wrote !== null && wrote <= LC_ACTIVE_MIN) return act('reply_now', true, 'reply on WhatsApp now, the patient is active');
    if (x.stage === 'hot') return act('reply_now', true, 'call now, ready to book');
    return act('follow_up', true, 'call or message today');
  }
  if (purpose === 'followup' || purpose === 'rebook') {   // opted out / paused: still stopped later by W6 – Decide send, as before
    if (x.needs_human) return act('human_handoff', false, 'waiting for a person (Needs_Human)');
    if (x.assigned_to) return act('wait', false, `staff own this conversation (${owner})`);
    if (LC_DONE_INTENTS.includes(x.last_intent)) return act('no_action', false, done);
    if (x.next_action_future) return act('wait', false, planned());
    if (purpose === 'rebook') {
      if (x.last_inbound_at !== null && Number.isFinite(o.since) && x.last_inbound_at > o.since) return act('wait', false, 'the patient has written since the missed appointment');
      return act('rebook', true, 'no-show: offer a new time');
    }
    if (wrote !== null && wrote < LC_RECENT_MIN) return act('wait', false, `the patient wrote ${lcAgo(wrote)}`);
    if (x.stage === 'cold') return act('nurture', false, 'the AI rated this lead cold: no day-2 push');
    return act('follow_up', true, x.stage === 'hot' ? 'hot lead: day-2 follow-up first' : 'day-2 follow-up');
  }
  throw new Error(`nextBestAction: unknown purpose ${purpose}`);
}

// W3: what staff need in one look. WHO (name, phone), WHAT (AI summary or enquiry, likely service), RECENT (last intent, when),
// HOW HOT (stage, waiting time), NEXT (the action). brief = the template's "enquiry" value; text = message_text.
function lcStaffBrief(x, nba, o) {
  const tag = x.stage ? `[${x.stage.toUpperCase()}] ` : '';
  const what = (x.summary || x.enquiry || 'no details yet').replace(/[.\s]+$/, '');
  const service = x.service ? ` (${x.service})` : '';
  const recent = [x.last_intent ? x.last_intent.replace(/_/g, ' ') : '', x.minutes_since_inbound !== null ? `wrote ${lcAgo(x.minutes_since_inbound)}` : ''].filter(Boolean).join(', ');
  const tail = `${recent ? ` Last: ${recent}.` : ''} Next: ${nba.reason.replace(/[.\s]+$/, '')}.`;
  return {
    brief: lcText(`${tag}${what}${service}.${tail}`, 240),
    text: lcText(`New lead ${tag}${o.name} (${o.phone}) for ${o.clinic}, waiting ${o.waiting_minutes} min. ${what}${service}.${tail}`, 500),
  };
}

  const cfg = $('W6 – Config').first().json;
  const nowMs = Date.now();
  const DAY = 86400000;
  const IST = 5.5 * 3600 * 1000;
  const dayNo = (sec) => Math.floor((sec * 1000 + IST) / DAY);   // India calendar day number
  const today = dayNo(nowMs / 1000);
  const daysAgo = (sec) => today - dayNo(sec);                  // whole India calendar days ago (0 = today)
  const lookback = Number(cfg.noshow_lookback_days);
  const followupAfter = Number(cfg.followup_after_days);
  const lostAfter = Number(cfg.lost_after_days);
  const maxFollowups = Number(cfg.max_followups_per_run);
  const maxLost = Number(cfg.max_lost_per_run);
  const OPEN = ['New', 'Contacted'];                            // not booked, not lost, not converted
  const clinics = $('W6 – Add leads').all();
  const out = [];

  $input.all().forEach((conv, i) => {
    const { appointments, leads: leadRows, ...ctx } = clinics[i].json;
    const leads = {};
    for (const r of leadRows) leads[String(r.id)] = r.fields || {};
    const paused = new Set();
    for (const r of conv.json.records || []) {
      const f = r.fields || {};
      if (f.Automation_Paused === true && f.Lead) paused.add(String(f.Lead));
    }
    // What W13 and staff wrote to Conversations + LEADS -> the next best action per lead (lead-context.js). It only holds back.
    const conversations = lcConversations(conv.json.records || []);
    const nbaFor = (id, purpose, o) => nextBestAction(leadContext({ id, fields: leads[id] }, conversations[id], nowMs), purpose, o);
    const futureBooked = new Set();                             // leads that already have an upcoming appointment
    for (const a of appointments) {
      const f = a.fields || {};
      if (f.Status === 'Booked' && f.Lead && typeof f.Start === 'number' && f.Start * 1000 >= nowMs) futureBooked.add(String(f.Lead));
    }
    const person = (id) => {
      const f = leads[id];
      return {
        lead_row_id: Number(id),
        lead_id: f.Lead_ID || `row ${id}`,
        lead_name: String(f.Name || ''),
        lead_phone: String(f.Phone || ''),
        opted_out: f.Opted_Out === true,
        automation_paused: paused.has(id),
      };
    };
    const push = (json) => out.push({ json: { ...ctx, ...json }, pairedItem: { item: i } });

    // 1. No-show rebook: the newest no-show per patient from the last `lookback` days (not today), Rebook_Sent empty.
    const noShow = {};
    for (const a of appointments) {
      const f = a.fields || {};
      if (f.Status !== 'No-show' || f.Rebook_Sent || !f.Lead || typeof f.Start !== 'number') continue;
      const d = daysAgo(f.Start);
      if (d < 1 || d > lookback) continue;
      const id = String(f.Lead);
      if (!noShow[id] || f.Start > noShow[id].fields.Start) noShow[id] = a;
    }
    for (const [id, a] of Object.entries(noShow)) {
      if (!leads[id] || futureBooked.has(id)) continue;          // already rebooked: nothing to chase
      if (!nbaFor(id, 'rebook', { since: a.fields.Start }).allowed) continue;   // a person owns it, a call is planned, or they wrote since
      push({
        kind: 'rebook', template: 'noshow_rebook', ...person(id),
        flag_table: 'Appointments', flag_row_id: a.id, flag_column: 'Rebook_Sent', flag_value: a.fields.Rebook_Sent || null,
        booking_uid: a.fields.Booking_UID || `row ${a.id}`, service: String(a.fields.Service || ''), appt_start: a.fields.Start,
      });
    }

    // 2. One follow-up: open leads created `followupAfter` to `lostAfter - 1` days ago, Followup_Sent off, nothing booked.
    const isOpen = (r) => {
      const f = r.fields || {};
      return OPEN.includes(f.Status) && typeof f.Created_At === 'number' && !futureBooked.has(String(r.id));
    };
    const age = (r) => daysAgo(r.fields.Created_At);
    const oldestFirst = (a, b) => a.fields.Created_At - b.fields.Created_At;
    // No day-2 follow-up while a person must answer or owns the conversation, the patient wrote in the last 48 h, said not
    // interested / stop, the AI rated the lead cold, or a call-back is planned (Next_Action_At in the future). Hot leads first.
    // Without these fields: as before (the same leads, oldest first).
    const rank = (r) => leadContext(r, conversations[String(r.id)], nowMs).rank;
    leadRows
      .filter((r) => isOpen(r) && !r.fields.Followup_Sent && age(r) >= followupAfter && age(r) < lostAfter && nbaFor(String(r.id), 'followup').allowed)
      .sort((a, b) => rank(a) - rank(b) || oldestFirst(a, b))
      .slice(0, maxFollowups)
      .forEach((r) => push({
        kind: 'followup', template: 'followup_day2', ...person(String(r.id)),
        flag_table: 'LEADS', flag_row_id: r.id, flag_column: 'Followup_Sent', flag_value: r.fields.Followup_Sent ? 1 : null,
      }));

    // 3. Mark Lost: open leads `lostAfter`+ days old, unless staff have a call-back planned (Next_Action_At in the future).
    if (cfg.mark_lost !== false) {
      leadRows
        .filter((r) => isOpen(r) && age(r) >= lostAfter && !(typeof r.fields.Next_Action_At === 'number' && r.fields.Next_Action_At * 1000 > nowMs))
        .sort(oldestFirst)
        .slice(0, maxLost)
        .forEach((r) => push({ kind: 'lost', ...person(String(r.id)) }));
    }
  });
  return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
  const cc = (typeof $env !== 'undefined' && $env && /^[1-9]\d{0,2}$/.test(String($env.FLOWHQ_DEFAULT_COUNTRY_CODE || ''))) ? String($env.FLOWHQ_DEFAULT_COUNTRY_CODE) : '91';
  let digits = s.replace(/\D/g, '');
  if (s.startsWith('00')) digits = digits.slice(2);
  else if (!s.startsWith('+')) {                                  // written locally
    if (cc === '91') { if (!(digits.length === 12 && digits.startsWith('91'))) { if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1); digits = `91${digits}`; } }
    else digits = `${cc}${digits.replace(/^0+/, '')}`;
  }
  let valid = /^[1-9]\d{7,14}$/.test(digits);
  if (valid && digits.startsWith('91')) valid = /^91[6-9]\d{9}$/.test(digits);   // +91 numbers are Indian mobiles
  return { phone: valid ? `+${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

  const { phone: patient_phone } = normalizeIndianPhone($json.lead_phone);
  const { phone: test_phone } = normalizeIndianPhone($json.test_phone);
  const decision = decideSend({
    kind: 'marketing',                 // follow-ups: Automation_Paused stops them (guide, section 6)
    flag_value: $json.flag_value,
    opted_out: $json.opted_out,
    automation_paused: $json.automation_paused,
    patient_phone,
    test_mode: $json.test_mode,
    test_phone,
    now_ms: Date.now(),
  });
  return { json: { ...$json, decision, send: decision.send } };

const now = Math.floor(Date.now() / 1000);
const log = (record) => ({ Workflow: 'W6-followups', Record: record, Outcome: $json.kind === 'lost' ? 'ok' : $json.sent === true ? 'ok' : ($json.duplicate === true ? 'skipped' : 'failed'), Error: $json.kind === 'lost' ? '' : $json.sent === true ? '' : String($json.uncertain === true ? `uncertain: ${$json.send_error || 'no clear answer from Meta'} (not sent again; check the Send_Ledger and WhatsApp Manager)` : ($json.send_error || $json.send_status || 'not sent')).slice(0, 500), At: now });
if ($json.kind === 'lost') {
  return {
    json: {
      ...$json,
      patch_table: 'LEADS',
      patch: { records: [{ id: $json.lead_row_id, fields: { Status: 'Lost', Lost_Reason: 'No response' } }] },
      log: log(`${$json.lead_id} (lost: no response)`),
    },
  };
}
// after a real send: tick the flag on the row the message was about (rule 4: right after the send)
const value = $json.flag_column === 'Rebook_Sent' ? now : true;   // Rebook_Sent is a DateTime, Followup_Sent a Toggle
const record = $json.kind === 'rebook' ? `${$json.booking_uid} (rebook) ${$json.lead_id}` : `${$json.lead_id} (followup)`;
return {
  json: {
    ...$json,
    patch_table: $json.flag_table,
    patch: { records: [{ id: $json.flag_row_id, fields: { [$json.flag_column]: value } }] },
    log: log(record),
  },
};

const item = $json;

const name = item.lead_name || 'there';
const clinic = item.clinic_name || 'Clinic';
const booking_link = item.booking_link || '';

let template;
let template_params;
let message_text;

if (item.kind === 'rebook') {
  template = 'noshow_rebook';

  const t = new Date(Number(item.appt_start) * 1000);

  const date = t.toLocaleDateString('en-IN', {
    day: '2-digit',
    month: 'short',
