    type: 'message',
    role: 'assistant',
    model: resp.model || '',
    content: text ? [{ type: 'text', text }] : [],
    stop_reason: stop,
    usage: { input_tokens: u.prompt_tokens || 0, output_tokens: u.completion_tokens || 0, provider: 'openrouter', model: resp.model || '' },
  };
}

