// Facts that stay the same for every message of a clinic (cached with the rules when long enough).
function aiClinicFacts(x) {
  const lines = ['CLINIC', `- name: ${x.profile.clinic_name || 'the clinic'}`];
  lines.push(`- booking link: ${x.profile.booking_link ? 'available, write {{BOOKING_LINK}}' : 'none'}`);
  lines.push(x.profile.booking_mode === 'direct'
    ? '- booking: the system books directly when the patient names a free day and time from AVAILABILITY'
    : `- booking: patients book through the link (the system cannot book for them)${x.profile.booking_link ? '' : '; there is no link, so hand off booking requests'}`);
  lines.push('', 'KNOWLEDGE BASE');
  if (!x.kb.length) lines.push('- (empty: nothing about services, prices or policies is known)');
  for (const k of x.kb) lines.push(`[${k.ref}] (${k.category}) ${k.title}: ${k.content.replace(/\s*\n\s*/g, ' / ')}`);
  return lines.join('\n');
}

// Facts for this message: the clock, calendar, free times, the patient and the conversation.
function aiFacts(x) {
  const lines = [];
  const nowT = aiIst(x.now_ms);
  lines.push(`NOW: ${aiDayLabel(nowT.date)} ${nowT.date}, ${aiHHMM(nowT.minutes)} IST`);
  lines.push('', 'CALENDAR (use it to turn words into dates)');
  for (const d of x.calendar) lines.push(`- ${d.date} = ${d.weekday} ${d.label}${d.relative ? ` (${d.relative})` : ''}`);
  lines.push('', `AVAILABILITY (free appointment start times, ${x.slots.slot_minutes}-minute appointments, IST)`);
  if (!x.slots.known) lines.push(x.slots.unreadable ? '- not known right now. Do not offer any time.' : '- not known: the clinic hours are not set. Do not offer any time.');
  else if (!x.slots.days.length) lines.push('- no free times in the coming days');
  for (const d of x.slots.days) lines.push(`- ${d.date} (${d.label}): ${d.times.slice(0, 24).map(aiHHMM).join(', ')}`);
  const l = x.lead;
  lines.push('', 'PATIENT', `- name: ${l.name || 'unknown'}`, `- new contact: ${l.created ? 'yes, first message' : 'no'}`, `- CRM status: ${l.status || 'unknown'}`);
  if (l.summary) lines.push(`- earlier summary: ${l.summary}`);
  if (l.enquiry) lines.push(`- first enquiry: ${aiLine(l.enquiry, 300)}`);
  lines.push('', 'APPOINTMENTS (this patient, upcoming)');
  if (x.appointments_unknown) lines.push('- could not be read: hand off any question about the patient\'s appointments');
  else if (!x.appointments.length) lines.push('- none');
  for (const a of x.appointments) {
    const how = a.origin === 'calcom' ? 'booked online: the patient cancels or reschedules with the link' : 'booked on WhatsApp: the system can cancel or move it';
    lines.push(`- [${a.ref}] ${a.label}${a.service ? `, ${a.service}` : ''}${a.physio ? ` with ${a.physio}` : ''} (${how})`);
  }
  lines.push('', 'RECENT CONVERSATION (oldest first)');
  if (!x.history.length) lines.push('- none');
  for (const m of x.history) lines.push(`- ${m.dir}${m.at ? ` (${aiDayLabel(aiIst(m.at * 1000).date)} ${aiHHMM(aiIst(m.at * 1000).minutes)})` : ''}: ${m.text}`);
  return lines.join('\n');
}

function aiBuildRequest(x, cfg) {
  return {
    model: cfg.model,
    max_tokens: 1500,
    system: [
      { type: 'text', text: AI_RULES },
      { type: 'text', text: aiClinicFacts(x), cache_control: { type: 'ephemeral' } },   // rules + clinic facts: the stable prefix
      { type: 'text', text: aiFacts(x) },
    ],
    messages: [{ role: 'user', content: `<patient_message>\n${aiClean(x.text, 2000)}\n</patient_message>` }],
    output_config: { format: { type: 'json_schema', schema: AI_DECISION_SCHEMA } },
  };
}

// ---------------------------------------------------------------- reading Claude's answer
function aiParseResponse(resp) {
  if (!resp || typeof resp !== 'object') return { ok: false, error: 'no answer from Claude' };
  if (resp.error) return { ok: false, error: `Claude request failed: ${aiErrText(resp)}` };
  if (resp.type === 'error') return { ok: false, error: 'Claude returned an error' };
  if (resp.stop_reason === 'refusal') return { ok: false, error: 'Claude declined to answer' };
  if (resp.stop_reason === 'max_tokens') return { ok: false, error: 'Claude\'s answer was cut off (max_tokens)' };
  const block = (resp.content || []).find((b) => b && b.type === 'text');
  if (!block) return { ok: false, error: 'Claude returned no text' };
  try { return { ok: true, decision: JSON.parse(block.text) }; } catch (e) { return { ok: false, error: 'Claude returned something that is not JSON' }; }
}

// Structured outputs enforce the schema, but the answer is still checked: n8n never acts on an unchecked decision.
function aiValidateDecision(d) {
  const p = [];
  const isObj = (v) => v && typeof v === 'object' && !Array.isArray(v);
  const strOrNull = (v) => v === null || typeof v === 'string';
  if (!isObj(d)) return ['the decision is not an object'];
  if (!AI_INTENTS.includes(d.intent)) p.push(`unknown intent ${JSON.stringify(d.intent)}`);
  if (!AI_ACTIONS.includes(d.action)) p.push(`unknown action ${JSON.stringify(d.action)}`);
  if (typeof d.needs_human !== 'boolean') p.push('needs_human is not true/false');
  if (typeof d.confidence !== 'number' || !(d.confidence >= 0 && d.confidence <= 1)) p.push('confidence is not a number between 0 and 1');
  if (!AI_SENTIMENTS.includes(d.sentiment)) p.push('bad sentiment');
  if (!AI_STAGES.includes(d.lead_stage)) p.push('bad lead_stage');
  if (typeof d.reply !== 'string') p.push('reply is not text');
  if (typeof d.handoff_reason !== 'string') p.push('handoff_reason is not text');
  if (typeof d.lead_summary !== 'string') p.push('lead_summary is not text');
  if (!isObj(d.booking)) p.push('booking is missing');
  else {
    if (!strOrNull(d.booking.date) || (d.booking.date && !/^\d{4}-\d{2}-\d{2}$/.test(d.booking.date))) p.push('booking.date is not YYYY-MM-DD');
    if (!strOrNull(d.booking.time) || (d.booking.time && !/^([01]\d|2[0-3]):[0-5]\d$/.test(d.booking.time))) p.push('booking.time is not HH:MM');
    if (!(d.booking.time_window === null || Object.keys(AI_WINDOWS).includes(d.booking.time_window))) p.push('bad booking.time_window');
  }
  if (!strOrNull(d.appointment_ref)) p.push('appointment_ref is not text');
  if (!(d.follow_up_days === null || Number.isInteger(d.follow_up_days))) p.push('follow_up_days is not a whole number');
  if (!Array.isArray(d.kb_refs) || d.kb_refs.some((x) => typeof x !== 'string')) p.push('kb_refs is not a list');
  if (!strOrNull(d.likely_service)) p.push('likely_service is not text');
  if (!AI_PRIORITIES.includes(d.priority)) p.push('bad priority');
  if (typeof d.staff_note !== 'string') p.push('staff_note is not text');
  if (!Array.isArray(d.risk_flags) || d.risk_flags.some((x) => !AI_RISK_FLAGS.includes(x))) p.push('bad risk_flags');
  return p;
}

// ---------------------------------------------------------------- the fact check on the reply text
// Times in a text, as minutes after midnight. "5 pm", "5:30 PM", "17:30", "5 baje" (either 05:00 or 17:00).
function aiTimesIn(text) {
  let s = String(text || '');
  const found = [];
  s = s.replace(/\b(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?m\.?|p\.?m\.?)(?![a-z])/gi, (m, hh, mm, ap) => {
    const hNum = Number(hh) % 12 + (/^p/i.test(ap) ? 12 : 0);
    found.push([hNum * 60 + Number(mm || 0)]);
    return ' ';
  });
  // "5 baje" / "5 बजे": 05:00 or 17:00, unless a word before it says which ("subah", "shaam ko", "शाम", "रात"...)
  s = s.replace(/(?:\b(subah|subha|savere|sawere|morning|dopahar|shaam|sham|evening|raat|night)(?:\s+ko)?\s+|(सुबह|सवेरे|दोपहर|शाम|रात)(?:\s*को)?\s*)?\b(\d{1,2})(?:[:.](\d{2}))?\s*(?:baje\b|बजे)/gi, (m, wl, wd, hh, mm) => {
    const hNum = Number(hh) % 12;
    const min = Number(mm || 0);
    const q = String(wl || wd || '').toLowerCase();
    if (/dopahar|shaam|sham|evening|raat|night|दोपहर|शाम|रात/.test(q)) found.push([(hNum + 12) * 60 + min]);
    else if (q) found.push([hNum * 60 + min]);
    else found.push([hNum * 60 + min, (hNum + 12) * 60 + min]);
    return ' ';
  });
  s.replace(/\b([01]?\d|2[0-3])[:.]([0-5]\d)\b/g, (m, hh, mm) => { found.push([Number(hh) * 60 + Number(mm)]); return ' '; });
  return found;   // each entry = the readings of one mention
}
function aiAmountsIn(text) {
  const out = [];
  const re = /(?:₹|\brs\.?|\binr\b|\brupees?\b|\brupa(?:i)?ye\b|(?<![\u0900-\u0963\u0971-\u097F])(?:रुपये|रुपए|रुपयों|रूपये|रूपए|रु\.?)(?![\u0900-\u0963\u0971-\u097F]))\s*(\d+(?:,\d+)*(?:\.\d+)?)|(\d+(?:,\d+)*(?:\.\d+)?)\s*(?:₹|\/-|\brs\b\.?|\brupees?\b|\brupa(?:i)?ye\b|\binr\b|(?<![\u0900-\u0963\u0971-\u097F])(?:रुपये|रुपए|रुपयों|रूपये|रूपए|रु\.?)(?![\u0900-\u0963\u0971-\u097F]))/gi;   // Hindi rupee words: whole words only
  let m;
  while ((m = re.exec(String(text || '')))) out.push(String(m[1] || m[2]).replace(/,/g, '').replace(/\.0+$/, ''));
  return out;
}
const aiNumbersIn = (text) => (String(text || '').match(/\d[\d,]*(?:\.\d+)?/g) || []).map((n) => n.replace(/,/g, '').replace(/\.0+$/, ''));
const aiUrlsIn = (text) => String(text || '').match(/https?:\/\/[^\s)>\]]+/gi) || [];
const aiPhonesIn = (text) => (String(text || '').match(/\+?\d[\d\s-]{8,}\d/g) || []).map((p) => p.replace(/\D/g, '')).filter((p) => p.length >= 10);

function aiAllowedFacts(x) {
  const kbText = x.kb.map((k) => `${k.title} ${k.content}`).join('\n');
  const minutes = new Set();
  for (const t of aiTimesIn(kbText)) for (const v of t) minutes.add(v);
  if (x.slots.known) { minutes.add(x.slots.open); minutes.add(x.slots.close); }
  for (const d of x.slots.days) for (const m of d.times) minutes.add(m);
  for (const a of x.appointments) minutes.add(a.minutes);
  return {
    amounts: new Set(aiNumbersIn(kbText)),
    minutes,
    urls: new Set(aiUrlsIn(kbText).map((u) => u.replace(/[.,]+$/, ''))),
    phones: new Set(aiPhonesIn(kbText).map((p) => p.slice(-10))),
  };
}

// opts.skipTimes: offer_slots / book_slot check their times against the free slots themselves (and repair them).
function aiCheckReply(reply, allowed, opts) {
  const p = [];
  const r = String(reply || '');
  if (r.length > 1000) p.push('the reply is longer than 1000 characters');
  if (/[०-९]/.test(r)) p.push('the reply writes numbers in Devanagari digits, which the fact check cannot read');
  if (/साढ़े|बजकर|(सवा|पौने)\s*\d|\b(saadhe|sadhe|saade|paune|sawa|sava)\s*\d|\d\s*baj\s?kar\b/i.test(r)) p.push('the reply writes a time or amount in words (saadhe / sawa / paune / bajkar), which the fact check cannot read');
  for (const a of aiAmountsIn(r)) if (!allowed.amounts.has(a)) p.push(`price ${a} is not in the knowledge base`);
  if (!(opts && opts.skipTimes)) for (const readings of aiTimesIn(r)) if (!readings.some((m) => allowed.minutes.has(m))) p.push(`time ${aiHHMM(readings[readings.length - 1])} is not a free slot, appointment or opening time`);
  for (const u of aiUrlsIn(r)) if (!allowed.urls.has(u.replace(/[.,]+$/, ''))) p.push(`link ${u} is not in the knowledge base`);
  for (const ph of aiPhonesIn(r)) if (!allowed.phones.has(ph.slice(-10))) p.push('a phone number that is not in the knowledge base');
  for (const ph of (r.match(/\{\{[^}]*\}\}/g) || [])) if (!AI_PLACEHOLDERS.includes(ph)) p.push(`unknown placeholder ${ph}`);
  return p;
}

// ---------------------------------------------------------------- links
function aiCalOrigin(bookingLink) { const m = String(bookingLink || '').match(/^(https?:\/\/[^/?#]+)/i); return m ? m[1] : ''; }
function aiBookingLink(bookingLink, date) {
  if (!bookingLink) return '';
  if (!date) return bookingLink;
  return `${bookingLink}${bookingLink.includes('?') ? '&' : '?'}date=${date}&month=${date.slice(0, 7)}`;
}
function aiFillLinks(reply, links) {
  let out = String(reply || '');
  for (const [ph, url] of Object.entries(links || {})) if (url) out = out.split(ph).join(url);
  const left = out.match(/\{\{[A-Z_]+\}\}/g);
  return { text: out, missing: left || [] };
}

// ---------------------------------------------------------------- decision -> plan (what to write, what to send)
function aiEmptyPlan(route, reason) {
  return { route, intent: '', action: route, confidence: 0, reason: aiLine(reason, 300), reply: '', links: {}, action_writes: [], lead_patch: {}, conversation_patch: {}, booked: null, cancelled: null, notes: [] };
}
function aiToHandoff(plan, x, cfg, reason) {
  const t = plan.triage || { priority: 'normal', flags: [], note: '' };
  const why = aiLine(reason, 300) || 'needs a person';
  const label = t.priority === 'urgent' ? 'URGENT · ' : t.priority === 'high' ? 'HIGH · ' : '';
  plan.route = 'handoff';
  plan.action = 'handoff';
  plan.reason = aiLine(`${label}${t.note || why}`, 300);   // what staff read in the alert and in Handoff_Reason
  if (t.note && t.note !== why && !plan.notes.includes(`hand-off: ${why}`)) plan.notes.push(`hand-off: ${why}`);
  plan.reply = x.profile.handoff_reply;
  plan.links = {};
  plan.action_writes = [];
  plan.booked = null;
  plan.cancelled = null;
  delete plan.lead_patch.Status;
  delete plan.lead_patch.Next_Action_At;
  plan.conversation_patch.Needs_Human = true;
  plan.conversation_patch.Handoff_Reason = plan.reason;
  if (cfg.pause_on_handoff === true) plan.conversation_patch.Automation_Paused = true;
  return plan;
}

// A plan for a message the gates stopped before the AI (skip, opt_out, defer, failed, handoff).
function aiGatePlan(gate, x, cfg) {
  const plan = aiEmptyPlan(gate.route, gate.reason);
  plan.quiet = gate.quiet === true;
  if (gate.triage) plan.triage = gate.triage;
  if (gate.route === 'opt_out') { plan.intent = 'opt_out'; plan.lead_patch.Opted_Out = true; plan.conversation_patch.Last_Intent = 'opt_out'; }
  if (gate.route === 'handoff') aiToHandoff(plan, x, cfg, gate.reason);
  return plan;
}

// x: the context (aiContext); d: the checked decision, or null when the AI failed (-> a person takes over).
function aiPlan(d, x, cfg) {
  const plan = aiEmptyPlan('reply', '');
  const handoff = (reason) => aiToHandoff(plan, x, cfg, reason);
  if (!d) return handoff('the AI could not decide (no valid answer)');
  plan.intent = d.intent;
  plan.action = d.action;
  plan.confidence = d.confidence;
  plan.triage = aiTriage(d);
  if (d.intent === 'outcome_worse') {   // worse after a visit: always a person, at least HIGH, flagged medical; never advice by message
    plan.triage = { priority: plan.triage.priority === 'urgent' ? 'urgent' : 'high', flags: [...new Set([...plan.triage.flags, 'medical'])], note: plan.triage.note || 'Patient says they feel worse after the visit. Suggest: a clinician calls them today (no advice by message).' };
  }

  // what we learn about the lead, whatever happens next
  plan.lead_patch.Lead_Stage = d.lead_stage;
  if (aiClean(d.lead_summary, 10)) plan.lead_patch.AI_Summary = aiClean(d.lead_summary, 500);
  if (d.likely_service) {
    const svc = x.kb.find((k) => k.category === 'services' && k.title.toLowerCase() === String(d.likely_service).trim().toLowerCase());
    if (svc) plan.lead_patch.Likely_Service = svc.title;
  }
  plan.conversation_patch.Last_Intent = d.intent;

  // A3: urgent or any risk flag -> always a person
  if (plan.triage.priority === 'urgent') return handoff(d.handoff_reason || `urgent ${d.intent.replace(/_/g, ' ')}`);
  if (plan.triage.flags.length) return handoff(d.handoff_reason || `risk: ${plan.triage.flags.join(', ')}`);
  if (d.needs_human || d.action === 'handoff') return handoff(AI_INTENT_LABELS[d.intent] ? `${AI_INTENT_LABELS[d.intent]}${d.handoff_reason ? `: ${d.handoff_reason}` : ''}` : (d.handoff_reason || `intent ${d.intent}`));
  if (AI_HUMAN_INTENTS.includes(d.intent)) return handoff(`${AI_INTENT_LABELS[d.intent] || d.intent.replace(/_/g, ' ')}${d.handoff_reason ? `: ${d.handoff_reason}` : ''}`);
  // A4: confidence tiers. < min_confidence: a person. Below confidence_auto: informational answers only. Negative mood:
  // informational answers only. Appointment changes (writes) need confidence_write, checked after routing below.
  const tLow = aiNum(cfg.min_confidence, 0.65);
  const tAuto = aiNum(cfg.confidence_auto, 0.8);
  const tWrite = aiNum(cfg.confidence_write, 0.85);
  const informational = AI_INFO_INTENTS.includes(d.intent) && AI_INFO_ACTIONS.includes(d.action);
  if (d.confidence < tLow) return handoff(`low confidence (${d.confidence})`);
  if (d.confidence < tAuto && !informational) return handoff(`confidence ${d.confidence} is below ${tAuto} for ${d.action} (${d.intent})`);
  if (d.sentiment === 'negative' && !informational) return handoff(`negative sentiment (${d.intent})`);
  // A1 (live rule): no_reply only where silence makes sense; otherwise a person answers instead of dropping the message.
  if (d.action === 'no_reply') {
    if (AI_NO_REPLY_INTENTS.includes(d.intent)) { plan.route = 'no_reply'; return plan; }
    return handoff(`AI selected no_reply for ${d.intent}; a response is required`);
  }
  if (!aiClean(d.reply, 10)) return handoff('the AI gave no reply text');

  const slotAction = d.action === 'offer_slots' || d.action === 'book_slot' || (d.action === 'reschedule_appointment' && !!d.booking.time);
  const problems = aiCheckReply(d.reply, aiAllowedFacts(x), { skipTimes: slotAction });
  if (problems.length) {   // the details (which may quote an invented link) stay in Grist; the staff alert only says why
    plan.notes.push(`fact check: ${problems.slice(0, 3).join('; ')}`);
    return handoff('the AI reply failed the fact check (details in Messages > AI_Reason)');
  }
  plan.reply = aiClean(d.reply, 1000);
  aiRoute(d, x, plan, handoff);
  if (plan.route !== 'handoff' && plan.action_writes.length && d.confidence < tWrite) return handoff(`confidence ${d.confidence} is below ${tWrite} for an appointment change`);
  if (plan.route !== 'handoff') aiFinishLinks(plan, x, handoff);
  return plan;
}

function aiRoute(d, x, plan, handoff) {
  const freeOn = (date) => { const day = x.slots.days.find((s) => s.date === date); return day ? day.times : []; };
  const toMin = (hhmm) => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));
  const win = d.booking.time_window ? AI_WINDOWS[d.booking.time_window] : null;
  const offerText = (date, lead) => {   // the real free times (on/after the day asked, in the window asked), max 3
    const days = date ? x.slots.days.filter((s) => s.date >= date) : x.slots.days;
    const picks = [];
    for (const pass of win ? [true, false] : [false]) {
      for (const s of days) for (const m of s.times) if (picks.length < 3 && (!pass || (m >= win[0] && m < win[1]))) picks.push(`${s.label} ${ai12h(m)}`);
      if (picks.length) break;
    }
    if (!picks.length) return null;
    return `${lead} Free times: ${picks.join(', ')}. Which one would you like?`;
  };
  const appt = () => {
    if (d.appointment_ref) return x.appointments.find((a) => a.ref === d.appointment_ref) || null;
    return x.appointments.length === 1 ? x.appointments[0] : null;
  };

  if (d.action === 'offer_slots' || d.action === 'book_slot') {
    if (!x.slots.known) {
      if (!x.profile.booking_link) return handoff('the patient wants an appointment but the free times are not known (clinic hours not set or appointments unreadable)');
      if (aiTimesIn(plan.reply).length) plan.reply = 'Please choose a free time here: {{BOOKING_LINK}}';
      if (!plan.reply.includes('{{BOOKING_LINK}}')) plan.reply += '\n{{BOOKING_LINK}}';
      plan.route = 'offer_slots';
      return null;
    }
    if (d.booking.date && !x.calendar.some((c) => c.date === d.booking.date)) return handoff(`the requested date ${d.booking.date} is outside the next ${x.calendar.length} days`);
  }
  if (d.action === 'offer_slots') {
    // every time in the reply must be free on the day asked about (or on any day if no day was given)
    const okTimes = new Set(d.booking.date ? freeOn(d.booking.date) : x.slots.days.flatMap((s) => s.times));
    if (aiTimesIn(plan.reply).some((readings) => !readings.some((m) => okTimes.has(m) || m === x.slots.open || m === x.slots.close))) {
      const fallback = offerText(d.booking.date, 'Here are the free times.');
      if (!fallback) return handoff('no free times to offer');
      plan.reply = fallback;
      plan.notes.push('the AI offered a time that is not free; replaced by the real free times');
    }
    plan.route = 'offer_slots';
    plan.booking_date = d.booking.date;
    return null;
  }

  if (d.action === 'book_slot') {
    const date = d.booking.date;
    const time = d.booking.time;
    if (!date || !time || !freeOn(date).includes(toMin(time))) {
      const fallback = offerText(date, 'Sorry, that time is not available.');
      if (!fallback) return handoff('the requested time is not free and there are no free times to offer');
      plan.reply = fallback;
      plan.route = 'offer_slots';
      plan.booking_date = date;
      plan.notes.push(`requested ${date || '?'} ${time || '?'} is not a free slot`);
      return null;
    }
    const m = toMin(time);
    const day = x.calendar.find((c) => c.date === date);
    const label = `${aiDayLabel(date)} at ${ai12h(m)}`;
    const mentions = aiTimesIn(plan.reply);
    const wrongTime = !mentions.length || mentions.some((r) => !r.includes(m));
    const wrongDay = AI_DAY_WORDS.some((w) => new RegExp(`\\b${w}\\b`, 'i').test(plan.reply) && w !== day.weekday);
    const claimsBooked = x.profile.booking_mode !== 'direct' && /\b(booked|confirmed|(?:book|fix|confirm) (?:kar|ho) (?:di|diya|gayi|gaya|gai|chuki|chuka|chuke))\b|(?:बुक|कन्फर्म|पक्की|पक्का|फिक्स) (?:कर|हो) (?:दी|दिया|गई|गया|चुकी|चुका|चुके)/i.test(plan.reply);
    if (wrongTime || wrongDay || claimsBooked) {
      plan.reply = x.profile.booking_mode === 'direct' ? `Booked: ${label}. See you then!` : `${label} is free. Please confirm it here: {{BOOKING_LINK}}`;
      plan.notes.push('the AI reply did not state the right day and time (or called a link booking confirmed); replaced by a plain one');
    }
    if (x.profile.booking_mode === 'direct') {
      const start = Math.floor(aiIstMs(date, m) / 1000);
      plan.booked = { Booking_UID: `wa-${x.msg.wa_message_id}`.slice(0, 120), Lead: x.lead.row_id, Service: plan.lead_patch.Likely_Service || 'Appointment', Start: start, End: start + x.slots.slot_minutes * 60, Status: 'Booked' };
      plan.action_writes.push({ method: 'POST', table: 'Appointments', body: { records: [{ fields: plan.booked }] } });
      plan.lead_patch.Status = 'Booked';
      plan.reply = plan.reply.split('{{BOOKING_LINK}}').join('').trim();
    } else {
      if (!x.profile.booking_link) return handoff('booking_mode is link but the clinic has no booking_link');
      if (!plan.reply.includes('{{BOOKING_LINK}}')) plan.reply += '\n{{BOOKING_LINK}}';
    }
    plan.booking_date = date;
    plan.route = 'book_slot';
    return null;
  }

  if (d.action === 'cancel_appointment' || d.action === 'reschedule_appointment') {
    const resched = d.action === 'reschedule_appointment';
    if (x.appointments_unknown) return handoff('the appointments could not be read');
    if (!x.appointments.length) return handoff(`${resched ? 'reschedule' : 'cancel'} requested but this patient has no upcoming appointment`);
    const a = appt();
    if (!a) {
      plan.reply = `Which appointment do you mean? ${x.appointments.map((y, i) => `${i + 1}) ${y.label}`).join(', ')}`;
      plan.route = 'reply';
      plan.notes.push('several appointments: asked which one');
      return null;
    }
    if (a.origin === 'calcom') {   // Cal.com does the change; W4 then updates Grist
      const ph = resched ? '{{RESCHEDULE_LINK}}' : '{{CANCEL_LINK}}';
      const origin = aiCalOrigin(x.profile.booking_link) || 'https://cal.com';
      if (!plan.reply.includes(ph) || aiTimesIn(plan.reply).some((r) => !r.includes(a.minutes))) {
        plan.reply = `To ${resched ? 'change' : 'cancel'} your appointment on ${a.label}, please use this link: ${ph}`;
        plan.notes.push('the AI reply had no link (or a wrong time); replaced by a plain one');
      }
      plan.links[ph] = resched ? `${origin}/reschedule/${a.uid}` : `${origin}/booking/${a.uid}?cancel=true`;
      plan.route = resched ? 'reschedule_link' : 'cancel_link';
      return null;
    }
    // booked through WhatsApp (wa-...): change it in Grist directly
    if (!resched) {
      plan.action_writes.push({ method: 'PATCH', table: 'Appointments', body: { records: [{ id: a.row_id, fields: { Status: 'Cancelled' } }] } });
      plan.cancelled = a;
      if (/\{\{/.test(plan.reply) || aiTimesIn(plan.reply).some((r) => !r.includes(a.minutes))) plan.reply = `Your appointment on ${a.label} is cancelled.`;
      plan.route = 'cancelled';
      return null;
    }
    const date = d.booking.date;
    const time = d.booking.time;
    if (!date || !time || !freeOn(date).includes(toMin(time))) {
      const fallback = offerText(date, date && time ? 'Sorry, that time is not available.' : 'Sure.');
      if (!fallback) return handoff('reschedule requested but there are no free times to offer');
      if (!date || !time) { if (aiTimesIn(plan.reply).length) plan.reply = fallback; plan.route = 'offer_slots'; return null; }
      plan.reply = fallback;
      plan.route = 'offer_slots';
      return null;
    }
    const m = toMin(time);
    const start = Math.floor(aiIstMs(date, m) / 1000);
    plan.booked = { Booking_UID: `wa-${x.msg.wa_message_id}`.slice(0, 120), Lead: x.lead.row_id, Service: a.service || 'Appointment', Start: start, End: start + x.slots.slot_minutes * 60, Status: 'Booked' };
    plan.action_writes.push({ method: 'PATCH', table: 'Appointments', body: { records: [{ id: a.row_id, fields: { Status: 'Rescheduled' } }] } });
    plan.action_writes.push({ method: 'POST', table: 'Appointments', body: { records: [{ fields: plan.booked }] } });
    plan.cancelled = a;
    if (/\{\{/.test(plan.reply) || aiTimesIn(plan.reply).some((r) => !r.includes(m))) plan.reply = `Your appointment is moved to ${aiDayLabel(date)} at ${ai12h(m)}.`;
    plan.route = 'rescheduled';
    return null;
  }

  if (d.action === 'schedule_follow_up') {
    const days = Math.min(14, Math.max(1, Number.isInteger(d.follow_up_days) ? d.follow_up_days : 2));
    plan.lead_patch.Next_Action_At = Math.floor(x.now_ms / 1000) + days * 86400;
    plan.route = 'follow_up';
    return null;
  }
  plan.route = 'reply';
  return null;
}

// Every placeholder left in the reply needs a link, whatever the action.
function aiFinishLinks(plan, x, handoff) {
  if (plan.reply.includes('{{BOOKING_LINK}}') && !plan.links['{{BOOKING_LINK}}']) {
    if (!x.profile.booking_link) return handoff('the reply needs a booking link but Settings has no booking_link');
    plan.links['{{BOOKING_LINK}}'] = aiBookingLink(x.profile.booking_link, plan.booking_date || null);
  }
  for (const ph of ['{{CANCEL_LINK}}', '{{RESCHEDULE_LINK}}']) {
    if (plan.reply.includes(ph) && !plan.links[ph]) return handoff(`the reply uses ${ph} but there is no such appointment link`);
  }
  return null;
}

// ---------------------------------------------------------------- what to send through W12
function aiSendItems(plan, x, h) {
  const items = [];
  const base = { source_workflow: AI_WORKFLOW, wa_phone_number_id: x.clinic.wa_phone_number_id, grist_base_url: x.clinic.grist_base_url, doc_id: x.clinic.doc_id };
  const patientPhone = x.lead.phone;
  const testPhone = h.normalizeIndianPhone(x.profile.test_phone).phone;
  const replyRoutes = ['reply', 'offer_slots', 'book_slot', 'cancel_link', 'reschedule_link', 'cancelled', 'rescheduled', 'follow_up', 'handoff'];
  if (plan.reply && replyRoutes.includes(plan.route) && x.cfg.reply_mode === 'auto') {
    const filled = aiFillLinks(plan.reply, plan.links);
    if (!filled.missing.length) {
      const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: x.lead.opted_out, automation_paused: false, patient_phone: patientPhone, test_mode: x.profile.test_mode, test_phone: testPhone, now_ms: x.now_ms });
      items.push({ ...base, w13_kind: 'patient_reply', audience: 'patient', decision, message_type: 'text', text_body: filled.text, message_text: filled.text, template: '', lead_row_id: x.lead.row_id, lead_phone: patientPhone, last_inbound_at: x.msg.timestamp });
    }
  }
  if (plan.route === 'handoff') {
    const owner = h.normalizeIndianPhone(x.profile.owner_phone).phone;
    const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: owner, test_mode: x.profile.test_mode, test_phone: testPhone, now_ms: x.now_ms });
    const name = x.lead.name || 'WhatsApp patient';
    items.push({
      ...base, w13_kind: 'staff_alert', audience: 'staff', decision, template: x.cfg.staff_alert_template || 'human_handoff_alert',
      template_params: { clinic_name: x.profile.clinic_name, lead_name: name, lead_phone: patientPhone || '', reason: plan.reason.replace(/https?:\/\/\S+/gi, '[link]') },
      message_text: `Needs a person (${x.profile.clinic_name}): ${name}, ${patientPhone || ''} - ${plan.reason.replace(/https?:\/\/\S+/gi, '[link]')}`,
    });
  }
  return items;
}

// ---------------------------------------------------------------- the final CRM writes, after the sends
// sends: { patient: W12 result or null, staff: W12 result or null }. Returns { status, needs_human, writes }.
// trace (optional, A2): { gate, model, latency_ms, tokens_in, tokens_out, fallback } -> Run_Log Record / AI_Reason.
function aiTraceText(t) {
  if (!t) return '';
  const parts = [`gate=${t.gate || '-'}`];
  if (t.model) parts.push(String(t.model));
  if (Number.isFinite(t.latency_ms)) parts.push(`${Math.round(t.latency_ms)}ms`);
  if (Number.isFinite(t.tokens_in) || Number.isFinite(t.tokens_out)) parts.push(`tok ${Number.isFinite(t.tokens_in) ? t.tokens_in : '?'}/${Number.isFinite(t.tokens_out) ? t.tokens_out : '?'}`);
  if (t.fallback) parts.push('fallback');
  return parts.join(' ');
}
function aiFinalWrites(plan, x, sends, nowSec, trace) {
  if (plan.quiet) return { status: 'skipped', needs_human: false, writes: [] };
  const reply = sends.patient;
  const staff = sends.staff;
  const filled = aiFillLinks(plan.reply, plan.links);
  const quietHours = (r) => !!r && !r.sent && /quiet hours/i.test(`${r.send_error || ''} ${(r.decision && r.decision.reason) || ''}`);
  const fixed = { skip: 'skipped', opt_out: 'opted_out', defer: 'deferred', failed: 'failed', no_reply: 'no_reply' };
  let status;
  if (fixed[plan.route]) status = fixed[plan.route];
  else if (x.dry_run) status = 'dry_run';
  else if (!plan.reply) status = plan.route === 'handoff' ? 'handed_off' : 'no_reply';
  else if (filled.missing.length) status = 'failed';
  else if (x.cfg.reply_mode !== 'auto') status = plan.route === 'handoff' ? 'handed_off' : 'drafted';
  else if (!reply) status = 'failed';
  else if (reply.sent) status = plan.route === 'handoff' ? 'handed_off' : 'replied';
  else if (quietHours(reply) || (plan.route === 'handoff' && quietHours(staff))) status = 'deferred';
  else status = 'failed';

  let reason = plan.reason;
  if (filled.missing.length) reason = `link missing for ${filled.missing.join(', ')}`;
  else if (reply && !reply.sent) reason = [reason, `reply not sent: ${reply.send_error || (reply.decision && reply.decision.reason) || reply.send_status}`].filter(Boolean).join('; ');
  if (staff && !staff.sent) reason = [reason, `staff alert not sent: ${staff.send_error || (staff.decision && staff.decision.reason) || staff.send_status}`].filter(Boolean).join('; ');
  if (plan.notes && plan.notes.length) reason = [reason, ...plan.notes].filter(Boolean).join('; ');
  if (x.notes && x.notes.length) reason = [reason, ...x.notes].filter(Boolean).join('; ');
  const t = plan.triage;
  const tags = t ? [...(t.priority && t.priority !== 'normal' ? [t.priority] : []), ...(t.flags || [])] : [];
  if (tags.length) reason = `[${tags.join(' · ')}] ${reason}`;
  if (trace && trace.fallback) reason = `fallback: ${reason}`;
  const needsHuman = plan.route === 'handoff' || status === 'failed';
  const report = { status, needs_human: needsHuman, route: plan.route, reason: aiClean(reason, 500), reply: aiClean(filled.text, 2000) };
  if (x.dry_run) return { ...report, writes: [] };

  const writes = [];
  if (x.msg.row_id) {
    writes.push({ method: 'PATCH', table: 'Messages', body: { records: [{ id: x.msg.row_id, fields: {
      Intent: plan.intent || '', AI_Action: plan.route, AI_Confidence: Number(plan.confidence) || 0, AI_Status: status,
      Needs_Human: needsHuman, AI_Reply: aiClean(filled.text, 2000), AI_Reason: aiClean(reason, 500),
    } }] } });
  }
  if (status !== 'deferred') {   // deferred: the 08:05 run decides again from scratch, so nothing else changes now
    const conv = { ...plan.conversation_patch };
    if (needsHuman && plan.route !== 'skip') { conv.Needs_Human = true; if (!conv.Handoff_Reason) conv.Handoff_Reason = aiClean(reason, 300); }
    if (Object.keys(conv).length && x.conversation.row_id) writes.push({ method: 'PATCH', table: 'Conversations', body: { records: [{ id: x.conversation.row_id, fields: conv }] } });

    const lead = { ...plan.lead_patch };
    const answered = !!reply && reply.sent && plan.route !== 'handoff';   // a hand-off "we will reply" does not count: W3 keeps chasing staff
    if (answered && x.lead.status === 'New' && lead.Status !== 'Booked') lead.Status = 'Contacted';
    if (answered && !x.lead.first_response_at) lead.First_Response_At = nowSec;
    if (plan.route === 'handoff' && staff && staff.sent === true) lead.Escalated = true;   // staff were alerted: W3 does not escalate again
    if (Object.keys(lead).length && x.lead.row_id) writes.push({ method: 'PATCH', table: x.cfg.leads_table, body: { records: [{ id: x.lead.row_id, fields: lead }] } });
  }

  writes.push({ method: 'POST', table: 'Run_Log', body: { records: [{ fields: {
    Workflow: AI_WORKFLOW,
    Record: aiLine(`${x.lead.lead_id || 'lead'} ${x.msg.wa_message_id} ${plan.intent || '-'} -> ${plan.route} (${status})${trace ? ` | ${aiTraceText(trace)}` : ''}`, 200),
    Outcome: status === 'failed' ? 'failed' : (status === 'skipped' ? 'skipped' : 'ok'),
    Error: aiClean(reason, 500),
    At: nowSec,
  } }] } });
  return { ...report, writes };
}


const h = { normalizeIndianPhone, decideSend, inQuietHours, parseClock, parseDays };
// ---- this node ----
// What W12 answered -> the final CRM writes (aiFinalWrites): the message row (intent, action, status, reply), the conversation
// (Last_Intent, Needs_Human), the lead (stage, summary, Contacted, follow-up date), Run_Log. A missing W12 answer = not sent.
const b = $('W13 – Build Context').first().json;
const ready = $('W13 – Plan Ready').first().json;
const sends = { patient: null, staff: null };
let callError = '';
for (const it of $input.all()) {
  const r = it.json || {};
  if (r.w13_kind === 'patient_reply') sends.patient = r;
  else if (r.w13_kind === 'staff_alert') sends.staff = r;
  else if (r.error) callError = String(r.error.message || r.error).slice(0, 200);
}
const sentNothing = (kind) => ({ w13_kind: kind, sent: false, send_status: 'no_result', send_error: `W12 gave no result${callError ? `: ${callError}` : ''} (check W13 – Config > w12_workflow_id)` });
for (const it of b.x.dry_run ? [] : ready.send_items) {
  if (it.w13_kind === 'patient_reply' && !sends.patient) sends.patient = sentNothing('patient_reply');
  if (it.w13_kind === 'staff_alert' && !sends.staff) sends.staff = sentNothing('staff_alert');
}
// Decision trace for Run_Log (A2): which gate, model, time from context to decision, tokens, and whether the AI answer was unusable.
const p = $('W13 – Plan').first().json;
const u = p.usage || {};
const st = $('W13 – Start').first().json;
const trace = b.gate.route === 'ai' ? {
  gate: 'ai', model: u.model || st.openrouter_model || st.anthropic_model || '', latency_ms: Number(p.decided_at) - Number(b.t0),
  tokens_in: u.input_tokens, tokens_out: u.output_tokens, fallback: !!p.ai_error,
} : { gate: b.gate.route };
const fw = aiFinalWrites(ready.plan, b.x, sends, Math.floor(Date.now() / 1000), trace);
const c = $('W13 – Resolve Clinic').first().json;
const brief = (r) => (r ? { sent: r.sent === true, send_status: r.send_status || '', to: (r.decision && r.decision.to) || null, error: r.send_error || '' } : null);
const report = {
  status: fw.status, route: fw.route, needs_human: fw.needs_human, reason: fw.reason, reply: fw.reply, intent: ready.plan.intent || '',
  test_case: b.x.test_case, dry_run: b.x.dry_run, sends: { patient: brief(sends.patient), staff: brief(sends.staff) },
};
if (!fw.writes.length) return [{ json: { report } }];
return fw.writes.map((w) => ({ json: { ...w, grist_base_url: c.grist_base_url, doc_id: c.doc_id, report } }));

// The run's result (what a caller such as the manual test gets back). A failed CRM write stops with an error so the error
// workflow (W11) alerts: the message row may still say "processing".
const report = $('W13 – Record Sends').first().json.report;
const p = $('W13 – Plan').first().json;
const failed = $input.all().filter((i) => i.json && i.json.error).map((i) => String(i.json.error.message || i.json.error).slice(0, 200));
if (failed.length) throw new Error(`W13: ${failed.length} Grist write(s) failed (${report.status}): ${failed[0]}`);
const would = ($('W13 – Split Sends').first().json.would_send || []).map((s) => ({ kind: s.w13_kind, send: !!(s.decision && s.decision.send), to: (s.decision && s.decision.to) || null, text: s.text_body || s.message_text }));
return [{ json: { ...report, decision: p.decision, ai_error: p.ai_error, usage: p.usage, would_send: would } }];

// Every active clinic of the Agency Registry (never a hard-coded clinic), one item each.
const cfg = $('W7 – Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');
const clinics = ($input.first().json.records || []).filter((r) => r.fields && String(r.fields.Active).toUpperCase() === 'TRUE' && String(r.fields.Grist_Doc_ID || '').trim());
return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
    wa_phone_number_id: String(r.fields.WA_Phone_Number_ID || '').trim(),
  },
  pairedItem: { item: 0 },
}));

// The clinic's Settings rows (Key -> Value) next to its registry row.
const clinics = $('W7 – Split clinics').all();
return $input.all().map((item, i) => {
  const s = {};
  for (const r of item.json.records || []) {
    const f = r.fields || {};
    if (f.Key) s[String(f.Key).trim()] = f.Value;
  }
  return { json: { ...clinics[i].json, clinic_name: String(s.clinic_name || clinics[i].json.registry_clinic_name || ''), settings: s }, pairedItem: { item: i } };
});

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- this node ----
// Who gets a check-in now (cmOutcomePlan): the newest Completed visit per patient that ended after_hours..max_hours ago, Outcome_Sent
// empty, no check-in in the last min_days_between days, no future Booked visit, nobody from staff owning the conversation.
// Only for clinics with Settings > outcome_checkin = on (missing = off: switch it on once the outcome_check template is approved).
const cfg = $('W7 – Config').first().json;
const clinics = $('W7 – Add settings').all();
const appts = $('W7 – Appointments').all();
const leads = $('W7 – Leads').all();
const now = Date.now();
const out = [];
$input.all().forEach((conv, i) => {
  const c = clinics[i].json;
  if (!cmOn(c.settings.outcome_checkin)) return;
  const plan = cmOutcomePlan(appts[i].json.records || [], leads[i].json.records || [], conv.json.records || [], now, cfg);
  for (const it of plan.items.slice(0, Number(cfg.max_per_run) || 30)) {
    out.push({
      json: { grist_base_url: c.grist_base_url, doc_id: c.doc_id, clinic_name: c.clinic_name, wa_phone_number_id: c.wa_phone_number_id, test_mode: c.settings.TEST_MODE, test_phone: c.settings.TEST_PHONE, ...it },
      pairedItem: { item: i },
    });
  }
});
return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
  const cc = (typeof $env !== 'undefined' && $env && /^[1-9]\d{0,2}$/.test(String($env.FLOWHQ_DEFAULT_COUNTRY_CODE || ''))) ? String($env.FLOWHQ_DEFAULT_COUNTRY_CODE) : '91';
  let digits = s.replace(/\D/g, '');
  if (s.startsWith('00')) digits = digits.slice(2);
  else if (!s.startsWith('+')) {                                  // written locally
    if (cc === '91') { if (!(digits.length === 12 && digits.startsWith('91'))) { if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1); digits = `91${digits}`; } }
    else digits = `${cc}${digits.replace(/^0+/, '')}`;
  }
  let valid = /^[1-9]\d{7,14}$/.test(digits);
  if (valid && digits.startsWith('91')) valid = /^91[6-9]\d{9}$/.test(digits);   // +91 numbers are Indian mobiles
  return { phone: valid ? `+${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

// ---- TEMPORARY TEST SWITCH: quiet hours (pasted from n8n/snippets/quiet-hours-switch.js - keep identical) ----
const DISABLE_QUIET_HOURS_FOR_TEST = false;   // true = skip ONLY the 21:00-08:00 IST quiet-hours check; false = the original rule
const originalInQuietHours = inQuietHours;   // the original rule from send-guard.js, unchanged
inQuietHours = (nowMs) => (DISABLE_QUIET_HOURS_FOR_TEST ? false : originalInQuietHours(nowMs));   // eslint-disable-line no-func-assign
// ---- end of the test switch ----
// ---- this node ----
// CLAUDE.md rules 4 and 5: sent flag, Opted_Out, Automation_Paused (this is not a transactional message), quiet hours, TEST_MODE.
// A patient without a valid phone number is never messaged, not even in TEST_MODE.
const { phone: patient_phone } = normalizeIndianPhone($json.lead_phone);
const { phone: test_phone } = normalizeIndianPhone($json.test_phone);
const decision = patient_phone
  ? decideSend({
    kind: 'marketing',
    flag_value: $json.flag_value,
    opted_out: $json.opted_out,
    automation_paused: $json.automation_paused,
    patient_phone,
    test_mode: $json.test_mode,
    test_phone,
    now_ms: Date.now(),
  })
  : { send: false, to: null, reason: 'no valid patient phone', test_mode: isTestMode($json.test_mode) };
return { json: { ...$json, patient_phone, decision, send: decision.send } };

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- this node ----
// The item for W12 (free text inside the 24 h window, else the approved template) + the claim: the sent flag is written BEFORE the
// send (next node). If that write fails, nothing is sent and W11 alerts; a message is never sent twice.
const now = Math.floor(Date.now() / 1000);
const message = cmPatientMessage($json, $json.clinic_name, now);
const flag = $json.kind === 'outcome' ? 'Outcome_Sent' : 'Review_Sent';
return {
  json: {
    ...$json,
    ...message,
    audience: 'patient',
    source_workflow: 'W7-outcome-nudge',
    lead_phone: $json.patient_phone,
    claim: { records: [{ id: $json.appt_row_id, fields: { [flag]: now } }] },
  },
};

// One Run_Log row per attempt (the weekly report counts them). Not sent = failed, with W12's reason; the flag stays set (one attempt
// per visit: a broken template or number can never make this section message the patient again and again).
const ok = $json.sent === true;
const d = $json.decision || {};
return {
  json: {
    ...$json,
    log: {
      Workflow: 'W7-outcome-nudge',
      Record: `${$json.booking_uid} ${$json.lead_id}${d.test_mode ? ' (TEST_MODE)' : ''}`.slice(0, 200),
      Outcome: ok ? 'ok' : 'failed',
      Error: ok ? '' : String($json.send_error || $json.send_status || 'not sent').slice(0, 500),
      At: Math.floor(Date.now() / 1000),
    },
  },
};

// Every active clinic of the Agency Registry (never a hard-coded clinic), one item each.
const cfg = $('W8 – Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');
const clinics = ($input.first().json.records || []).filter((r) => r.fields && String(r.fields.Active).toUpperCase() === 'TRUE' && String(r.fields.Grist_Doc_ID || '').trim());
return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
    wa_phone_number_id: String(r.fields.WA_Phone_Number_ID || '').trim(),
  },
  pairedItem: { item: 0 },
}));

// The clinic's Settings rows (Key -> Value) next to its registry row.
const clinics = $('W8 – Split clinics').all();
return $input.all().map((item, i) => {
  const s = {};
  for (const r of item.json.records || []) {
    const f = r.fields || {};
    if (f.Key) s[String(f.Key).trim()] = f.Value;
  }
  return { json: { ...clinics[i].json, clinic_name: String(s.clinic_name || clinics[i].json.registry_clinic_name || ''), settings: s }, pairedItem: { item: i } };
});

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- this node ----
// Who gets a review request now (cmReviewPlan): the newest Completed visit per patient that ended after_hours..max_days ago, Review_Sent
// empty, not asked in the last min_days_between days. No filter on mood or complaints (Google: no review gating).
// Only for clinics with Settings > review_requests = on (missing = off: switch it on once the review_request template is approved).
// No usable Settings > review_link: nothing is sent; once a day (config_warning_hour, IST) a Run_Log warning says how many are waiting.
const cfg = $('W8 – Config').first().json;
const clinics = $('W8 – Add settings').all();
const appts = $('W8 – Appointments').all();
const leads = $('W8 – Leads').all();
const now = Date.now();
const nowSec = Math.floor(now / 1000);
const hourIST = new Date(now + 5.5 * 3600 * 1000).getUTCHours();
const out = [];
$input.all().forEach((conv, i) => {
  const c = clinics[i].json;
  if (!cmOn(c.settings.review_requests)) return;
  const plan = cmReviewPlan(appts[i].json.records || [], leads[i].json.records || [], conv.json.records || [], now, cfg, c.settings.review_link);
  if (!plan.link_ok && plan.waiting > 0 && hourIST === Number(cfg.config_warning_hour)) {
    out.push({
      json: {
        kind: 'config_warning', grist_base_url: c.grist_base_url, doc_id: c.doc_id,
        log: { Workflow: 'W8-review-request', Record: 'config: Settings > review_link', Outcome: 'skipped', Error: `Settings > review_link is missing or not an https:// link: ${plan.waiting} review request(s) are waiting and none is sent until it is set.`, At: nowSec },
      },
      pairedItem: { item: i },
    });
  }
  for (const it of plan.items.slice(0, Number(cfg.max_per_run) || 30)) {
    out.push({
      json: { grist_base_url: c.grist_base_url, doc_id: c.doc_id, clinic_name: c.clinic_name, wa_phone_number_id: c.wa_phone_number_id, test_mode: c.settings.TEST_MODE, test_phone: c.settings.TEST_PHONE, ...it },
      pairedItem: { item: i },
    });
  }
});
return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
  const cc = (typeof $env !== 'undefined' && $env && /^[1-9]\d{0,2}$/.test(String($env.FLOWHQ_DEFAULT_COUNTRY_CODE || ''))) ? String($env.FLOWHQ_DEFAULT_COUNTRY_CODE) : '91';
  let digits = s.replace(/\D/g, '');
  if (s.startsWith('00')) digits = digits.slice(2);
  else if (!s.startsWith('+')) {                                  // written locally
    if (cc === '91') { if (!(digits.length === 12 && digits.startsWith('91'))) { if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1); digits = `91${digits}`; } }
    else digits = `${cc}${digits.replace(/^0+/, '')}`;
  }
  let valid = /^[1-9]\d{7,14}$/.test(digits);
  if (valid && digits.startsWith('91')) valid = /^91[6-9]\d{9}$/.test(digits);   // +91 numbers are Indian mobiles
  return { phone: valid ? `+${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

// ---- TEMPORARY TEST SWITCH: quiet hours (pasted from n8n/snippets/quiet-hours-switch.js - keep identical) ----
const DISABLE_QUIET_HOURS_FOR_TEST = false;   // true = skip ONLY the 21:00-08:00 IST quiet-hours check; false = the original rule
const originalInQuietHours = inQuietHours;   // the original rule from send-guard.js, unchanged
inQuietHours = (nowMs) => (DISABLE_QUIET_HOURS_FOR_TEST ? false : originalInQuietHours(nowMs));   // eslint-disable-line no-func-assign
// ---- end of the test switch ----
// ---- this node ----
// CLAUDE.md rules 4 and 5: sent flag, Opted_Out, Automation_Paused (this is not a transactional message), quiet hours, TEST_MODE.
// A patient without a valid phone number is never messaged, not even in TEST_MODE.
const { phone: patient_phone } = normalizeIndianPhone($json.lead_phone);
const { phone: test_phone } = normalizeIndianPhone($json.test_phone);
const decision = patient_phone
  ? decideSend({
    kind: 'marketing',
    flag_value: $json.flag_value,
    opted_out: $json.opted_out,
    automation_paused: $json.automation_paused,
    patient_phone,
    test_mode: $json.test_mode,
    test_phone,
    now_ms: Date.now(),
  })
  : { send: false, to: null, reason: 'no valid patient phone', test_mode: isTestMode($json.test_mode) };
return { json: { ...$json, patient_phone, decision, send: decision.send } };

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- this node ----
// The item for W12 (free text inside the 24 h window, else the approved template) + the claim: the sent flag is written BEFORE the
// send (next node). If that write fails, nothing is sent and W11 alerts; a message is never sent twice.
const now = Math.floor(Date.now() / 1000);
const message = cmPatientMessage($json, $json.clinic_name, now);
const flag = $json.kind === 'outcome' ? 'Outcome_Sent' : 'Review_Sent';
return {
  json: {
    ...$json,
    ...message,
    audience: 'patient',
    source_workflow: 'W8-review-request',
    lead_phone: $json.patient_phone,
    claim: { records: [{ id: $json.appt_row_id, fields: { [flag]: now } }] },
  },
};

// One Run_Log row per attempt (the weekly report counts them). Not sent = failed, with W12's reason; the flag stays set (one attempt
// per visit: a broken template or number can never make this section message the patient again and again).
const ok = $json.sent === true;
const d = $json.decision || {};
return {
  json: {
    ...$json,
    log: {
      Workflow: 'W8-review-request',
      Record: `${$json.booking_uid} ${$json.lead_id}${d.test_mode ? ' (TEST_MODE)' : ''}`.slice(0, 200),
      Outcome: ok ? 'ok' : 'failed',
      Error: ok ? '' : String($json.send_error || $json.send_status || 'not sent').slice(0, 500),
      At: Math.floor(Date.now() / 1000),
    },
  },
};

// Every active clinic of the Agency Registry (never a hard-coded clinic), one item each.
const cfg = $('W9 – Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');
const clinics = ($input.first().json.records || []).filter((r) => r.fields && String(r.fields.Active).toUpperCase() === 'TRUE' && String(r.fields.Grist_Doc_ID || '').trim());
return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
    wa_phone_number_id: String(r.fields.WA_Phone_Number_ID || '').trim(),
  },
  pairedItem: { item: 0 },
}));

// The clinic's Settings rows (Key -> Value) next to its registry row.
const clinics = $('W9 – Split clinics').all();
return $input.all().map((item, i) => {
  const s = {};
  for (const r of item.json.records || []) {
    const f = r.fields || {};
    if (f.Key) s[String(f.Key).trim()] = f.Value;
  }
  return { json: { ...clinics[i].json, clinic_name: String(s.clinic_name || clinics[i].json.registry_clinic_name || ''), settings: s }, pairedItem: { item: i } };
});

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- this node ----
// Every number of the report, computed here from Grist rows (cmWeeklyMetrics), for the week that ended last Monday 00:00 IST.
// The AI request carries these numbers only; the AI never computes or changes one.
const cfg = $('W9 – Config').first().json;
const clinics = $('W9 – Add settings').all();
const leads = $('W9 – Leads').all();
const appts = $('W9 – Appointments').all();
const convs = $('W9 – Conversations').all();
const msgs = $('W9 – Messages').all();
const now = Date.now();
const win = cmWeekWindow(now);
const cap = Number(cfg.read_limit) || 5000;
return $input.all().map((logs, i) => {
  const c = clinics[i].json;
  const runlog = logs.json.records || [];
  const metrics = cmWeeklyMetrics({
    leads: leads[i].json.records, appointments: appts[i].json.records, conversations: convs[i].json.records, messages: msgs[i].json.records, runlog,
  }, now, win, { messages: cap, runlog: cap });
  // the owner gets this week's report on WhatsApp at most once (a Run_Log "owner WhatsApp <week>" row with Outcome ok = already sent)
  const ownerSent = runlog.some((r) => (r.fields || {}).Workflow === 'W9-weekly-report' && (r.fields || {}).Outcome === 'ok' && (r.fields || {}).Record === `owner WhatsApp ${win.label}`);
  return {
    json: {
      grist_base_url: c.grist_base_url, doc_id: c.doc_id, clinic_name: c.clinic_name, wa_phone_number_id: c.wa_phone_number_id,
      owner_on: cmOn(c.settings.weekly_report_whatsapp), owner_phone: c.settings.owner_phone, test_mode: c.settings.TEST_MODE, test_phone: c.settings.TEST_PHONE, owner_sent: ownerSent,
      review_link_set: !!cmHttps(c.settings.review_link), window: win, metrics, body: cmReportRequest(metrics, cfg.openrouter_model),
    },
    pairedItem: { item: i },
  };
});

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- this node ----
// The AI's answer is checked line by line (cmCheckAiReport: a line quoting a number that is not in the computed data is dropped);
// no answer / bad answer = the report is written from the numbers alone. Sections 2-6 are always written by code.
const x = $('W9 – Metrics').item.json;
const ai = cmCheckAiReport($json, cmAllowedNumbers(x.metrics));
const rep = cmRenderReport(x.metrics, ai, x.clinic_name, x.window, x.review_link_set);
const { body, ...rest } = x;
return {
  json: {
    ...rest,
    report: rep.text, headline: rep.headline, top_action: rep.top_action, ai_error: ai.error, ai_dropped: ai.dropped,
    owner_send: x.owner_on === true,
    log: { Workflow: 'W9-weekly-report', Record: rep.text, Outcome: 'ok', Error: ai.error ? `AI text not used: ${ai.error}`.slice(0, 500) : '', At: Math.floor(Date.now() / 1000) },
  },
};

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
  const cc = (typeof $env !== 'undefined' && $env && /^[1-9]\d{0,2}$/.test(String($env.FLOWHQ_DEFAULT_COUNTRY_CODE || ''))) ? String($env.FLOWHQ_DEFAULT_COUNTRY_CODE) : '91';
  let digits = s.replace(/\D/g, '');
  if (s.startsWith('00')) digits = digits.slice(2);
  else if (!s.startsWith('+')) {                                  // written locally
    if (cc === '91') { if (!(digits.length === 12 && digits.startsWith('91'))) { if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1); digits = `91${digits}`; } }
    else digits = `${cc}${digits.replace(/^0+/, '')}`;
  }
  let valid = /^[1-9]\d{7,14}$/.test(digits);
  if (valid && digits.startsWith('91')) valid = /^91[6-9]\d{9}$/.test(digits);   // +91 numbers are Indian mobiles
  return { phone: valid ? `+${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

// ---- TEMPORARY TEST SWITCH: quiet hours (pasted from n8n/snippets/quiet-hours-switch.js - keep identical) ----
const DISABLE_QUIET_HOURS_FOR_TEST = false;   // true = skip ONLY the 21:00-08:00 IST quiet-hours check; false = the original rule
const originalInQuietHours = inQuietHours;   // the original rule from send-guard.js, unchanged
inQuietHours = (nowMs) => (DISABLE_QUIET_HOURS_FOR_TEST ? false : originalInQuietHours(nowMs));   // eslint-disable-line no-func-assign
// ---- end of the test switch ----
// ---- this node ----
// Optional: the headline and the first recommended action to Settings > owner_phone, through W12 (template weekly_owner_report).
// Off unless Settings > weekly_report_whatsapp = on (after Meta approves the template). Quiet hours and TEST_MODE (-> TEST_PHONE) apply;
// at most once per week.
const r = $('W9 – Report').item.json;
const { phone: owner } = normalizeIndianPhone(r.owner_phone);
const { phone: test_phone } = normalizeIndianPhone(r.test_phone);
const off = (reason) => ({ send: false, to: null, reason, test_mode: isTestMode(r.test_mode) });
const decision = !r.owner_send ? off('Settings > weekly_report_whatsapp is off')
  : !owner ? off('Settings > owner_phone is missing or not a valid mobile number')
    : decideSend({ kind: 'transactional', flag_value: r.owner_sent ? 1 : null, opted_out: false, automation_paused: false, patient_phone: owner, test_mode: r.test_mode, test_phone, now_ms: Date.now() });
const params = { clinic_name: r.clinic_name || 'the clinic', week: r.window.label, summary: r.headline, action: r.top_action };
return {
  json: {
    grist_base_url: r.grist_base_url, doc_id: r.doc_id, wa_phone_number_id: r.wa_phone_number_id, week: r.window.label,
    audience: 'staff', source_workflow: 'W9-weekly-report', template: 'weekly_owner_report', template_params: params,
    message_text: `Weekly report ${params.week} for ${params.clinic_name}: ${params.summary}. Next: ${params.action}`,
    decision, send: decision.send,
  },
};

const ok = $json.sent === true;
return {
  json: {
    ...$json,
    log: { Workflow: 'W9-weekly-report', Record: `owner WhatsApp ${$json.week}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : String($json.send_error || $json.send_status || 'not sent').slice(0, 500), At: Math.floor(Date.now() / 1000) },
  },
};

// Every active clinic of the Agency Registry (never a hard-coded clinic), one item each.
const cfg = $('W10 – Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');
const clinics = ($input.first().json.records || []).filter((r) => r.fields && String(r.fields.Active).toUpperCase() === 'TRUE' && String(r.fields.Grist_Doc_ID || '').trim());
return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
    wa_phone_number_id: String(r.fields.WA_Phone_Number_ID || '').trim(),
  },
  pairedItem: { item: 0 },
}));

// The staff replies waiting to go: Messages rows with Direction Out and Send ticked (W10 – Pending), one item each.
const clinics = $('W10 – Split clinics').all();
const out = [];
$input.all().forEach((res, i) => {
  for (const row of res.json.records || []) {
    out.push({ json: { ...clinics[i].json, row, conversation_id: Number((row.fields || {}).Conversation) || 0 }, pairedItem: { item: i } });
  }
});
return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
  const cc = (typeof $env !== 'undefined' && $env && /^[1-9]\d{0,2}$/.test(String($env.FLOWHQ_DEFAULT_COUNTRY_CODE || ''))) ? String($env.FLOWHQ_DEFAULT_COUNTRY_CODE) : '91';
  let digits = s.replace(/\D/g, '');
  if (s.startsWith('00')) digits = digits.slice(2);
  else if (!s.startsWith('+')) {                                  // written locally
    if (cc === '91') { if (!(digits.length === 12 && digits.startsWith('91'))) { if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1); digits = `91${digits}`; } }
    else digits = `${cc}${digits.replace(/^0+/, '')}`;
  }
  let valid = /^[1-9]\d{7,14}$/.test(digits);
  if (valid && digits.startsWith('91')) valid = /^91[6-9]\d{9}$/.test(digits);   // +91 numbers are Indian mobiles
  return { phone: valid ? `+${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- TEMPORARY TEST SWITCH: quiet hours (pasted from n8n/snippets/quiet-hours-switch.js - keep identical) ----
const DISABLE_QUIET_HOURS_FOR_TEST = false;   // true = skip ONLY the 21:00-08:00 IST quiet-hours check; false = the original rule
const originalInQuietHours = inQuietHours;   // the original rule from send-guard.js, unchanged
inQuietHours = (nowMs) => (DISABLE_QUIET_HOURS_FOR_TEST ? false : originalInQuietHours(nowMs));   // eslint-disable-line no-func-assign
// ---- end of the test switch ----
// ---- this node ----
// cmStaffReplyCheck: send / reject (written back on the row, Send unticked) / hold (quiet hours: it goes at 08:00) / none.
// Opted_Out, a valid phone, the 24 h WhatsApp window, quiet hours and TEST_MODE apply. Automation_Paused, Needs_Human and Assigned_To
// do not stop a person's reply (they stop automated messages).
const x = $('W10 – Collect').item.json;
const settings = {};
for (const r of $('W10 – Settings').item.json.records || []) {
  const f = r.fields || {};
  if (f.Key) settings[String(f.Key).trim()] = f.Value;
}
const conv = ($('W10 – Conversation').item.json.records || [])[0] || null;
const lead = ($json.records || [])[0] || null;
const check = cmStaffReplyCheck(x.row, conv, lead, settings, Date.now(), { normalizeIndianPhone, decideSend });
const base = { grist_base_url: x.grist_base_url, doc_id: x.doc_id, row_id: x.row.id, conversation_id: x.conversation_id, check, send: check.action === 'send' };
if (!base.send) return { json: base };
return {
  json: {
    ...base,
    message: {
      ...check.message, decision: check.decision, audience: 'patient', source_workflow: 'W10-staff-reply',
      wa_phone_number_id: x.wa_phone_number_id, grist_base_url: x.grist_base_url, doc_id: x.doc_id,
      w10: { row_id: x.row.id, conversation_id: x.conversation_id },
    },
  },
};

// Pasted from n8n/snippets/clinic-modules.js - keep identical.
const CM_ROLE = { hot: 0, warm: 1, cold: 2 };
const CM_DONE_INTENTS = ['not_interested', 'opt_out'];
const CM_TEXT_WINDOW_SEC = 24 * 3600 - 5 * 60;   // WhatsApp free-text window (as W12), minus a margin
const CM_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const CM_IST = 5.5 * 3600;

function cmText(v, max) { return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max); }
function cmSec(v) { return typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : null; }
function cmDate(sec) { const t = new Date((sec + CM_IST) * 1000); return `${String(t.getUTCDate()).padStart(2, '0')} ${CM_MONTHS[t.getUTCMonth()]} ${t.getUTCFullYear()}`; }
function cmHttps(v) { const s = cmText(v, 500); return /^https:\/\/[^\s<>"']+$/i.test(s) ? s : ''; }
function cmFirstName(v) { return cmText(v, 60).split(' ')[0] || 'there'; }
function cmIsAutomation(sentBy) { return /^W\d+(?!\w)/.test(cmText(sentBy, 80)); }   // "W5-reminders", "W13-ai-receptionist", "W12"... else a person
// A per-clinic switch in Settings (outcome_checkin, review_requests, weekly_report_whatsapp): on / true / yes / 1. Missing = OFF,
// like ai_mode: a clinic gets these messages only after it is switched on (its WhatsApp templates are approved per number).
function cmOn(v) { return ['on', 'true', 'yes', '1'].includes(cmText(v, 10).toLowerCase()); }

// Conversations -> { lead id: { needs_human, paused, assigned, last_intent, last_inbound_at } } (newest inbound wins the intent).
function cmConversations(records) {
  const out = {};
  for (const r of Array.isArray(records) ? records : []) {
    const f = (r && r.fields) || {};
    const id = String(f.Lead === null || f.Lead === undefined ? '' : f.Lead);
    if (!/^[1-9]\d*$/.test(id)) continue;
    const c = out[id] || (out[id] = { needs_human: false, paused: false, assigned: '', last_intent: '', last_inbound_at: null, conversation_id: r.id });
    if (f.Needs_Human === true) c.needs_human = true;
    if (f.Automation_Paused === true) c.paused = true;
    if (!c.assigned) c.assigned = cmText(f.Assigned_To, 60);
    const at = cmSec(f.Last_Inbound_At);
    if (at !== null && (c.last_inbound_at === null || at >= c.last_inbound_at)) { c.last_inbound_at = at; c.last_intent = cmText(f.Last_Intent, 40); }
  }
  return out;
}
const cmEnd = (f) => cmSec(f.End) || (cmSec(f.Start) ? f.Start + 45 * 60 : null);   // no End: assume a 45-minute session

// ---------------------------------------------------------------- W7: outcome check-in after a Completed appointment
// cfg: { after_hours, max_hours, min_days_between }. One check-in per patient: the newest Completed visit that ended after_hours to
// max_hours ago, Outcome_Sent empty; none if another check-in went to them in the last min_days_between days, if they already have
// a future Booked visit (staff see them soon), or if a person owns the conversation / they said not interested or stop.
function cmOutcomePlan(appointments, leadRows, convRecords, nowMs, cfg) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_hours) * 3600;
  const gap = Number(cfg.min_days_between) * 86400;
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  const held = [];
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead)) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Outcome_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    const a = due[0];
    const hold = (why) => held.push({ appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, reason: why });
    const lf = leads[lead];
    if (!lf) { hold('lead not found'); continue; }
    if (list.some((x) => cmSec(x.fields.Outcome_Sent) && now - x.fields.Outcome_Sent < gap)) { hold('a check-in went to this patient recently'); continue; }
    if (list.some((x) => x.fields.Status === 'Booked' && cmSec(x.fields.Start) && x.fields.Start > now)) { hold('the patient already has a future appointment'); continue; }
    const c = convs[lead];
    if (c && (c.needs_human || c.assigned)) { hold('a person owns this conversation'); continue; }
    if (c && CM_DONE_INTENTS.includes(c.last_intent)) { hold('the patient said not interested / stop'); continue; }
    items.push({
      kind: 'outcome', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Outcome_Sent || null,
      service: cmText(a.fields.Service, 80), physio: cmText(a.fields.Physio, 60), appt_end: cmEnd(a.fields), last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, held };
}

// ---------------------------------------------------------------- W8: review request after a Completed appointment
// cfg: { after_hours, max_days, min_days_between }. The newest Completed visit per patient that ended after_hours to max_days ago,
// Review_Sent empty; none if this patient was asked in the last min_days_between days. Deliberately NO filter on mood, outcome or
// complaints: choosing whom to ask by how happy they are is "review gating", against Google's review policy. Opted out, paused,
// quiet hours and TEST_MODE are applied by W8 – Decide send. Without a review link nothing is planned (reported as waiting).
function cmReviewPlan(appointments, leadRows, convRecords, nowMs, cfg, reviewLink) {
  const now = Math.floor(nowMs / 1000);
  const after = Number(cfg.after_hours) * 3600;
  const max = Number(cfg.max_days) * 86400;
  const gap = Number(cfg.min_days_between) * 86400;
  const link = cmHttps(reviewLink);
  const leads = {};
  for (const r of leadRows || []) leads[String(r.id)] = r.fields || {};
  const convs = cmConversations(convRecords);
  const byLead = {};
  for (const a of appointments || []) (byLead[String((a.fields || {}).Lead)] = byLead[String((a.fields || {}).Lead)] || []).push(a);
  const items = [];
  let waiting = 0;
  for (const [lead, list] of Object.entries(byLead)) {
    if (!/^[1-9]\d*$/.test(lead) || !leads[lead]) continue;
    const due = list.filter((a) => {
      const f = a.fields || {};
      const end = cmEnd(f);
      return f.Status === 'Completed' && !f.Review_Sent && end !== null && now - end >= after && now - end <= max;
    }).sort((x, y) => cmEnd(y.fields) - cmEnd(x.fields));
    if (!due.length) continue;
    if (list.some((x) => cmSec(x.fields.Review_Sent) && now - x.fields.Review_Sent < gap)) continue;
    if (!link) { waiting++; continue; }
    const a = due[0];
    const lf = leads[lead];
    const c = convs[lead];
    items.push({
      kind: 'review', appt_row_id: a.id, booking_uid: a.fields.Booking_UID || `row ${a.id}`, lead_row_id: Number(lead),
      lead_id: lf.Lead_id || lf.Lead_ID || `row ${lead}`, lead_name: cmText(lf.Name, 60), lead_phone: cmText(lf.Phone, 20),
      opted_out: lf.Opted_Out === true, automation_paused: !!(c && c.paused), flag_value: a.fields.Review_Sent || null,
      review_link: link, last_inbound_at: c ? c.last_inbound_at : null,
    });
  }
  return { items, waiting, link_ok: !!link };
}

// W7 / W8: the message for W12. Free text when the patient wrote in the last 24 h (no template needed), else the approved template.
// The text is the template's wording, so the Grist inbox (and W13 reading the history) shows what the patient got.
function cmPatientMessage(item, clinicName, nowSec) {
  const name = cmFirstName(item.lead_name);
  const clinic = cmText(clinicName, 80) || 'the clinic';
  let text;
  let template;
  let params;
  if (item.kind === 'outcome') {
    const service = item.service || 'visit';
    text = `Hi ${name}, thank you for visiting ${clinic} for your ${service}. How are you feeling now? Just reply here: better, the same or worse. If you would like another appointment, tell us and we will help.`;
    template = 'outcome_check';
    params = { name, clinic_name: clinic, service };
  } else {
    text = `Hi ${name}, thank you for choosing ${clinic}. If you have a minute, we would be grateful for your honest review here: ${item.review_link} Thank you!`;
    template = 'review_request';
    params = { name, clinic_name: clinic, review_link: item.review_link };
  }
  const inWindow = cmSec(item.last_inbound_at) !== null && nowSec - item.last_inbound_at < CM_TEXT_WINDOW_SEC;
  return inWindow
    ? { message_type: 'text', text_body: text, message_text: text, template: '', template_params: {} }
    : { message_type: 'template', text_body: '', message_text: text, template, template_params: params };
}

// ---------------------------------------------------------------- W9: weekly report
// The week that ended last Monday 00:00 IST (W9 runs Monday morning): [start, end) in epoch seconds.
function cmWeekWindow(nowMs) {
  const istDay = Math.floor((nowMs / 1000 + CM_IST) / 86400);   // days since 1970-01-01 in India
  const weekday = (istDay + 4) % 7;                               // 0 = Sunday ... 1 = Monday
  const monday = istDay - ((weekday + 6) % 7);                    // this week's Monday
  const end = monday * 86400 - CM_IST;
  const start = end - 7 * 86400;
  return { start, end, label: `${cmDate(start)} to ${cmDate(end - 1)}` };
}

// Every number in the report, computed from Grist rows. data: { leads, appointments, conversations, messages, runlog } (records);
// caps: { messages, runlog } = the row limits used for the reads (to say when a count may be incomplete).
function cmWeeklyMetrics(data, nowMs, win, caps = {}) {
  const now = Math.floor(nowMs / 1000);
  const inWeek = (t) => cmSec(t) !== null && t >= win.start && t < win.end;
  const f = (r) => (r && r.fields) || {};
  const count = (list, fn) => list.filter(fn).length;
  const leads = (data.leads || []).map(f);
  const newLeads = leads.filter((l) => inWeek(l.Created_At));
  const bySource = {};
  for (const l of newLeads) { const s = cmText(l.Source, 30) || 'unknown'; bySource[s] = (bySource[s] || 0) + 1; }
  const firsts = newLeads.filter((l) => cmSec(l.First_Response_At) && cmSec(l.Created_At) && l.First_Response_At >= l.Created_At)
    .map((l) => Math.round((l.First_Response_At - l.Created_At) / 60)).sort((a, b) => a - b);
  const stage = { hot: 0, warm: 0, cold: 0, not_rated: 0 };
  for (const l of newLeads) stage[Object.prototype.hasOwnProperty.call(CM_ROLE, l.Lead_Stage) ? l.Lead_Stage : 'not_rated']++;
  const appts = (data.appointments || []).map(f);
  const week = appts.filter((a) => inWeek(a.Start));
  const msgs = (data.messages || []).map(f);
  const inbound = msgs.filter((m) => m.Direction === 'In' && inWeek(m.Created_At));
  const st = (s) => count(inbound, (m) => m.AI_Status === s);
  const intent = (s) => count(inbound, (m) => m.Intent === s);
  const convs = (data.conversations || []).map(f);
  const logs = (data.runlog || []).map(f).filter((l) => inWeek(l.At));
  const sent = (wf, re) => count(logs, (l) => l.Workflow === wf && l.Outcome === 'ok' && (!re || re.test(String(l.Record || ''))));
  const failures = {};
  for (const l of logs) if (l.Outcome === 'failed') failures[l.Workflow || 'unknown'] = (failures[l.Workflow || 'unknown'] || 0) + 1;
  return {
    leads: {
      new: newLeads.length,
      by_source: bySource,
      contacted: count(newLeads, (l) => !!cmSec(l.First_Response_At) || (l.Status && l.Status !== 'New')),
      booked: count(newLeads, (l) => l.Status === 'Booked' || l.Status === 'Converted'),
      still_new: count(newLeads, (l) => l.Status === 'New'),
      median_first_response_minutes: firsts.length ? firsts[Math.floor((firsts.length - 1) / 2)] : null,
      stage,
      opted_out_total: count(leads, (l) => l.Opted_Out === true),
    },
    appointments: {
      this_week: week.length,
      completed: count(week, (a) => a.Status === 'Completed'),
      no_show: count(week, (a) => a.Status === 'No-show'),
      cancelled: count(week, (a) => a.Status === 'Cancelled'),
      rescheduled: count(week, (a) => a.Status === 'Rescheduled'),
      still_marked_booked: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start < now - 3600),
      booked_next_7_days: count(appts, (a) => a.Status === 'Booked' && cmSec(a.Start) && a.Start >= now && a.Start < now + 7 * 86400),
    },
    ai: {
      patient_messages: inbound.length,
      replied: st('replied'), drafted: st('drafted'), handed_off: st('handed_off'), no_reply: st('no_reply'),
      skipped: st('skipped'), deferred: st('deferred'), failed: st('failed'), opted_out: st('opted_out'),
      outcome_better: intent('outcome_better'), outcome_same: intent('outcome_same'), outcome_worse: intent('outcome_worse'),
    },
    people: {
      waiting_for_a_person: count(convs, (c) => c.Needs_Human === true),
      paused_conversations: count(convs, (c) => c.Automation_Paused === true),
      staff_replies_sent: count(msgs, (m) => m.Direction === 'Out' && !cmIsAutomation(m.Sent_By) && ['sent', 'delivered', 'read'].includes(m.Status) && inWeek(m.Created_At)),
    },
    sent: {
      speed_to_lead_alerts: sent('W3-speed-to-lead'), reminders: sent('W5-reminders'), day2_followups: sent('W6-followups', /\(followup\)/),
      noshow_rebooks: sent('W6-followups', /\(rebook\)/), outcome_checkins: sent('W7-outcome-nudge'), review_requests: sent('W8-review-request'),
      ai_runs: sent('W13-ai-receptionist'),
    },
    failures: { total: Object.values(failures).reduce((a, b) => a + b, 0), by_workflow: failures },
    incomplete: { messages: !!caps.messages && (data.messages || []).length >= caps.messages, run_log: !!caps.runlog && (data.runlog || []).length >= caps.runlog },
  };
}

// The issues, from the numbers only (deterministic, always shown).
function cmIssues(m, reviewLinkSet) {
  const out = [];
  if (m.appointments.still_marked_booked) out.push(`${m.appointments.still_marked_booked} past appointment(s) are still marked Booked: mark them Completed or No-show (check-ins, reviews and no-show rebooking depend on it).`);
  if (m.people.waiting_for_a_person) out.push(`${m.people.waiting_for_a_person} conversation(s) are waiting for a person (Needs_Human).`);
  if (m.leads.still_new) out.push(`${m.leads.still_new} of this week's new leads were never contacted (Status still New).`);
  if (m.ai.outcome_worse) out.push(`${m.ai.outcome_worse} patient(s) said they feel worse after a visit.`);
  if (m.failures.total) out.push(`${m.failures.total} automation step(s) failed this week (see Run_Log, Outcome = failed).`);
  if (!reviewLinkSet) out.push('Settings > review_link is not set, so no review requests are sent.');
  if (m.incomplete.messages || m.incomplete.run_log) out.push('Very busy week: some message / log counts may be incomplete (read limit reached).');
  return out;
}

// Every number the AI may quote: each numeric value in the metrics, as text.
function cmAllowedNumbers(m) {
  const set = new Set();
  const walk = (v) => { if (typeof v === 'number' && Number.isFinite(v)) set.add(String(v)); else if (v && typeof v === 'object') Object.values(v).forEach(walk); };
  walk(m);
  return set;
}

const CM_REPORT_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['summary', 'observations', 'recommendations'],
  properties: { summary: { type: 'string' }, observations: { type: 'array', items: { type: 'string' } }, recommendations: { type: 'array', items: { type: 'string' } } },
};
const CM_REPORT_RULES = [
  'You write the weekly report of a physiotherapy clinic for its owner, from DATA only.',
  'Use ONLY numbers that appear in DATA, exactly as written. Never add, subtract, total, average or turn numbers into percentages; never write numbers as words; never mention money, prices, dates or names.',
  'summary: 2 or 3 short sentences on the week. observations: at most 3 facts from DATA worth the owner\'s attention. recommendations: at most 3 practical next steps for the clinic team (no medical advice).',
  'Answer with JSON only.',
].join('\n');

// One OpenRouter request per clinic per week (the model and credential are W13's: openrouter + openai/gpt-4o-mini).
function cmReportRequest(m, model) {
  return {
    model, temperature: 0.2, max_tokens: 700,
    messages: [{ role: 'system', content: CM_REPORT_RULES }, { role: 'user', content: `DATA\n${JSON.stringify(m)}` }],
    response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: CM_REPORT_SCHEMA } },
    provider: { require_parameters: true },
  };
}

const CM_NUMBER_WORDS = /\b(zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty|thirty|forty|fifty|hundred|thousand|dozen|half|double|twice|triple)\b/i;
// Every line the AI wrote is kept only if each number in it is one of the computed numbers, and it has no number words, % or ₹.
function cmCheckLine(line, allowed) {
  const s = cmText(line, 300).replace(/https?:\/\/\S+/gi, '');
  if (!s) return '';
  if (CM_NUMBER_WORDS.test(s) || /[%₹$]|\bRs\.?\b|\bINR\b/i.test(s)) return '';
  const nums = s.match(/\d+(?:[.,]\d+)?/g) || [];
  return nums.every((n) => allowed.has(n.replace(/,/g, ''))) ? s : '';
}
// OpenRouter's answer (or n8n's { error } item) -> { summary, observations, recommendations, dropped, error }.
function cmCheckAiReport(resp, allowed) {
  const empty = (error) => ({ summary: '', observations: [], recommendations: [], dropped: 0, error });
  if (!resp || resp.error) return empty(`AI not available: ${cmText(resp && resp.error && (resp.error.message || resp.error), 200) || 'no answer'}`);
  const c = resp.choices && resp.choices[0];
  let j;
  try { j = JSON.parse(c && c.message && c.message.content); } catch (e) { return empty('AI answer was not JSON'); }
  if (!j || typeof j.summary !== 'string' || !Array.isArray(j.observations) || !Array.isArray(j.recommendations)) return empty('AI answer did not match the schema');
  let dropped = 0;
  const keep = (list, n) => list.slice(0, n).map((x) => { const v = cmCheckLine(x, allowed); if (!v) dropped++; return v; }).filter(Boolean);
  const summary = cmText(j.summary, 600).split(/(?<=[.!?])\s+/).map((x) => { const v = cmCheckLine(x, allowed); if (!v && x.trim()) dropped++; return v; }).filter(Boolean).join(' ');
  return { summary, observations: keep(j.observations, 3), recommendations: keep(j.recommendations, 3), dropped, error: '' };
}

// The report: sections 2-6 are written by code from the numbers; 1 and 7 come from the checked AI text, or from code if it failed.
function cmRenderReport(m, ai, clinicName, win, reviewLinkSet) {
  const L = m.leads; const A = m.appointments; const I = m.ai; const P = m.people; const S = m.sent;
  const sources = Object.entries(L.by_source).sort((a, b) => b[1] - a[1]).map(([k, v]) => `${k} ${v}`).join(', ') || 'none';
  const headline = `${L.new} new leads (${L.booked} booked), ${A.completed} visits completed, ${A.no_show} no-show, ${A.cancelled} cancelled, ${I.handed_off} AI hand-offs, ${P.waiting_for_a_person} waiting for a person`;
  const issues = cmIssues(m, reviewLinkSet);
  const fallbackActions = issues.length ? issues.slice(0, 3) : ['No open issues this week: keep marking appointments Completed / No-show the same day.'];
  const summary = ai.summary || `This week: ${headline}.`;
  const recs = ai.recommendations.length ? ai.recommendations : fallbackActions;
  const lines = [
    `WEEKLY REPORT - ${clinicName} - ${win.label}`,
    'Numbers: computed by n8n from Grist. Summary, observations and recommendations: written by AI from those numbers only (checked: a line quoting any other number is dropped).',
    '',
    '1. Executive summary', summary, ...ai.observations.map((o) => `- ${o}`),
    '',
    '2. Lead performance',
    `- New leads: ${L.new} (${sources})`,
    `- Contacted: ${L.contacted} | booked: ${L.booked} | still New: ${L.still_new}`,
    `- Median first response: ${L.median_first_response_minutes === null ? 'n/a' : `${L.median_first_response_minutes} min`}`,
    `- Stage of new leads: hot ${L.stage.hot} | warm ${L.stage.warm} | cold ${L.stage.cold} | not rated ${L.stage.not_rated}`,
    `- Opted out (all time): ${L.opted_out_total}`,
    '',
    '3. Appointment performance (appointments that started this week)',
    `- Total ${A.this_week} | completed ${A.completed} | no-show ${A.no_show} | cancelled ${A.cancelled} | rescheduled ${A.rescheduled}`,
    `- Past appointments still marked Booked: ${A.still_marked_booked} | booked for the next 7 days: ${A.booked_next_7_days}`,
    '',
    '4. AI receptionist and hand-offs',
    `- Patient messages ${I.patient_messages} | AI replied ${I.replied} | handed to staff ${I.handed_off} | drafts ${I.drafted} | no reply needed ${I.no_reply} | deferred overnight ${I.deferred} | skipped ${I.skipped} | failed ${I.failed} | opted out ${I.opted_out}`,
    `- Check-in answers: better ${I.outcome_better} | same ${I.outcome_same} | worse ${I.outcome_worse}`,
    `- Conversations waiting for a person now: ${P.waiting_for_a_person} | paused: ${P.paused_conversations} | staff replies sent: ${P.staff_replies_sent}`,
    '',
    '5. Follow-up performance (messages sent)',
    `- Speed-to-lead alerts ${S.speed_to_lead_alerts} | reminders ${S.reminders} | day-2 follow-ups ${S.day2_followups} | no-show rebooks ${S.noshow_rebooks} | check-ins ${S.outcome_checkins} | review requests ${S.review_requests}`,
    '',
    '6. Important issues',
    ...(issues.length ? issues.map((x) => `- ${x}`) : ['- none']),
    '',
    `7. Recommended actions (${ai.recommendations.length ? 'AI suggestions' : 'suggested by the rules'}, not facts)`,
    ...recs.map((x) => `- ${x}`),
  ];
  if (ai.error) lines.push('', `(AI text not used: ${ai.error})`);
  else if (ai.dropped) lines.push('', `(${ai.dropped} AI line(s) dropped: they quoted a number that is not in the data)`);
  return { text: lines.join('\n'), headline, top_action: recs[0] };
}

// ---------------------------------------------------------------- W10: staff reply from the Grist inbox
// A Messages row staff wrote (Direction Out, Send ticked). -> { action: send | reject | hold | none, ... }.
//   reject: not sendable as it is (patch Status + AI_Reason, Send unticked)   hold: quiet hours, goes out at 08:00 (note only)
// Staff replies are human messages: Automation_Paused (stops AUTOMATED messages) does not block them; Opted_Out does.
function cmStaffReplyCheck(row, conv, lead, settings, nowMs, h) {
  const f = (row && row.fields) || {};
  const cf = (conv && conv.fields) || null;
  const lf = (lead && lead.fields) || {};
  const nowSec = Math.floor(nowMs / 1000);
  const reject = (status, why) => ({ action: 'reject', status, reason: why, patch: { Send: false, Status: status, AI_Reason: cmText(why, 500) } });
  if (f.Direction !== 'Out' || f.Send !== true) return { action: 'none', reason: 'not a pending staff reply' };
  if (cmText(f.WA_Message_ID, 120) || ['sent', 'delivered', 'read'].includes(f.Status)) return { action: 'reject', status: f.Status || 'sent', reason: 'already sent: not sent again', patch: { Send: false } };
  const body = String(f.Body === null || f.Body === undefined ? '' : f.Body).trim();
  if (!body) return reject('failed', 'empty message: write the reply in Body, then tick Send');
  if (cmText(f.Template, 80)) return reject('failed', 'templates are not sent from the inbox: leave Template empty and write the reply in Body');
  if (!cf) return reject('failed', 'conversation not found: add the reply in the patient\'s conversation');
  const patient = h.normalizeIndianPhone(cf.Phone || lf.Phone).phone;
  if (!patient) return reject('failed', 'the conversation has no valid patient phone number');
  if (lf.Opted_Out === true) return reject('failed', 'the patient opted out (STOP): not sent. Untick Leads > Opted_Out only if the patient asks to hear from you again');
  const last = cmSec(cf.Last_Inbound_At);
  if (last === null || nowSec - last >= CM_TEXT_WINDOW_SEC) return reject('needs_template', 'the patient\'s last message is older than 24 h: WhatsApp only allows an approved template now. Ask them to message you first, or call');
  const decision = h.decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: patient, test_mode: settings.TEST_MODE, test_phone: h.normalizeIndianPhone(settings.TEST_PHONE).phone, now_ms: nowMs });
  if (!decision.send && decision.reason === 'quiet hours') {
    const note = 'waiting: quiet hours (21:00-08:00 IST); it goes out at 08:00';
    return { action: 'hold', reason: note, patch: f.AI_Reason === note ? null : { AI_Reason: note } };
  }
  if (!decision.send) return reject('failed', `not sent: ${decision.reason}`);
  return {
    action: 'send', decision, reason: decision.reason,
    claim: { Send: false, Status: 'queued', AI_Reason: '', ...(cmSec(f.Created_At) ? {} : { Created_At: nowSec }), ...(cmText(f.Sent_By, 80) ? {} : { Sent_By: 'Staff' }) },
    message: { message_type: 'text', text_body: body.slice(0, 4096), message_text: body.slice(0, 2000), template: '', template_params: {}, last_inbound_at: last, lead_phone: patient, lead_row_id: Number(cf.Lead) || 0, inbox_row_id: row.id },
  };
}

// What W12 answered -> the writes for the staff row, the conversation and Run_Log.
function cmStaffReplyResult(rowId, res, nowSec) {
  const ok = res && res.sent === true;
  const err = cmText(res && res.send_error, 400);
  const status = ok ? 'sent' : /24-hour|24h window|131047/i.test(err) ? 'needs_template' : 'failed';
  const via = res && res.decision && res.decision.test_mode ? `TEST_MODE: sent to ${res.decision.to}` : '';
  return {
    message_patch: { Status: status, WA_Message_ID: ok ? cmText(res.wa_message_id, 120) : '', AI_Reason: ok ? [via, err].filter(Boolean).join('; ') : (err || 'not sent') },
    conversation_patch: ok ? { Unread: 0 } : null,
    log: { Workflow: 'W10-staff-reply', Record: `message ${rowId} (staff reply)${ok && res.wa_message_id ? ` ${cmText(res.wa_message_id, 80)}` : ''}`, Outcome: ok ? 'ok' : 'failed', Error: ok ? '' : (err || 'not sent'), At: nowSec },
  };
}


// ---- this node ----
// What W12 answered -> the staff row (Status, WA_Message_ID, AI_Reason), the conversation (Unread 0 once answered) and Run_Log.
// Needs_Human, Assigned_To and Automation_Paused are left exactly as staff set them.
const now = Math.floor(Date.now() / 1000);
const out = [];
$input.all().forEach((it, i) => {
  const j = it.json;
  const r = cmStaffReplyResult(j.w10.row_id, j, now);
  const at = { grist_base_url: j.grist_base_url, doc_id: j.doc_id };
  out.push({ json: { ...at, method: 'PATCH', table: 'Messages', body: { records: [{ id: j.w10.row_id, fields: r.message_patch }] } }, pairedItem: { item: i } });
  if (r.conversation_patch && j.w10.conversation_id) out.push({ json: { ...at, method: 'PATCH', table: 'Conversations', body: { records: [{ id: j.w10.conversation_id, fields: r.conversation_patch }] } }, pairedItem: { item: i } });
  out.push({ json: { ...at, method: 'POST', table: 'Run_Log', body: { records: [{ fields: r.log }] } }, pairedItem: { item: i } });
});
return out;

// Not sendable as written: the reason goes on the row (AI_Reason, Status) and Send is unticked, so it is never retried by itself;
// staff fix it and tick Send again. Quiet hours: only a note, the row stays ticked and goes out at 08:00.
const now = Math.floor(Date.now() / 1000);
const out = [];
$input.all().forEach((it, i) => {
  const j = it.json;
  const c = j.check || {};
  const at = { grist_base_url: j.grist_base_url, doc_id: j.doc_id };
  if (c.patch) out.push({ json: { ...at, method: 'PATCH', table: 'Messages', body: { records: [{ id: j.row_id, fields: c.patch }] } }, pairedItem: { item: i } });
  if (c.action === 'reject' && !/^already sent/.test(c.reason || '')) {
    out.push({ json: { ...at, method: 'POST', table: 'Run_Log', body: { records: [{ fields: { Workflow: 'W10-staff-reply', Record: `message ${j.row_id} (staff reply not sent)`, Outcome: 'failed', Error: String(c.reason || '').slice(0, 500), At: now } }] } }, pairedItem: { item: i } });
  }
});
return out;

// W2 META SIGNATURE CHECK. Meta signs the EXACT bytes of the POST (X-Hub-Signature-256 = sha256=HMAC-SHA256(App Secret, raw body)). The raw body comes from the
// Webhook node option "Raw Body" (binary property "data", default in-memory storage). Pasted from n8n/snippets/hmac-sha256.js and meta-signature.js - keep identical.
function utf8Bytes(str) {
  const out = [];
  for (const ch of String(str)) {
    const c = ch.codePointAt(0);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256Bytes(bytes) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));

  const msg = bytes.slice();
  const bitLen = bytes.length * 8;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  for (const w of [hi, lo]) msg.push((w >>> 24) & 255, (w >>> 16) & 255, (w >>> 8) & 255, w & 255);

  const w = new Array(64);
  for (let off = 0; off < msg.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = ((msg[off + 4 * i] << 24) | (msg[off + 4 * i + 1] << 16) | (msg[off + 4 * i + 2] << 8) | msg[off + 4 * i + 3]) >>> 0;
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  const out = [];
  for (const v of H) out.push((v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255);
  return out;
}

function hmacSha256Hex(key, message) {
  let k = utf8Bytes(key);
  if (k.length > 64) k = sha256Bytes(k);
  while (k.length < 64) k.push(0);
  const inner = sha256Bytes(k.map((b) => b ^ 0x36).concat(utf8Bytes(message)));
  const mac = sha256Bytes(k.map((b) => b ^ 0x5c).concat(inner));
  return mac.map((b) => b.toString(16).padStart(2, '0')).join('');
}

function safeEqual(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}


const META_SIG_MODES = ['enforce', 'log', 'off'];

// HMAC-SHA256 of raw bytes (an array of 0-255) with a text key -> hex. (hmacSha256Hex in hmac-sha256.js takes a text message.)
function hmacSha256HexBytes(key, bytes) {
  let k = utf8Bytes(key);
  if (k.length > 64) k = sha256Bytes(k);
  while (k.length < 64) k.push(0);
  const inner = sha256Bytes(k.map((b) => b ^ 0x36).concat(Array.from(bytes)));
  const mac = sha256Bytes(k.map((b) => b ^ 0x5c).concat(inner));
  return mac.map((b) => b.toString(16).padStart(2, '0')).join('');
}

const metaSigSecretUsable = (secret) => { const s = String(secret === null || secret === undefined ? '' : secret); return s.length >= 8 && !/^(REPLACE_|PASTE_)/i.test(s); };
const metaSigMode = (m) => { const s = String(m === null || m === undefined ? '' : m).trim().toLowerCase(); return META_SIG_MODES.includes(s) ? s : 'enforce'; };

// The raw body out of the Webhook node's binary property (default in-memory storage: .data is base64). Returns bytes or null.
function metaSigRawBytes(binary) {
  const d = binary && binary.data;
  if (!d || typeof d.data !== 'string' || d.id || d.data === 'filesystem-v2' || d.data === 'filesystem') return null;   // not inline: another storage mode
  if (typeof Buffer === 'undefined') return null;
  return Array.from(Buffer.from(d.data, 'base64'));
}

// in: { headers, binary, secret, mode }. Returns { state, ok, reason }.
//   state 'ok' = signature verified | 'skipped' = mode off | 'warn' = mode log and NOT verified | 'bad' = reject (mode enforce)
