return { json: { ...p, ledger_patch: { records: [{ id: row, fields: { Status: status, WA_Message_ID: r.wa_message_id || '', Error: String(r.send_error || '').slice(0, 300), Error_Code: Number.isFinite(Number(r.send_error_code)) ? Number(r.send_error_code) : 0, Updated_At: Math.floor(Date.now() / 1000) } }] } } };

// carry on with the send result (and note if the ledger write failed)
const { ledger_patch, ...rest } = $('W12 – Ledger result').first().json;
return { json: { ...rest, ledger_update_ok: !($json && $json.error) } };

// A send that Meta rejected or W12 found invalid (unknown template, empty variable, no key...) is logged: it used to vanish and be retried every run.
// "blocked" (allowlist, quiet hours, ledger unreachable) is normal and stays silent.
return $input.all().map((it) => { const j = it.json; return { json: { ...j, log: { Workflow: 'W3-speed-to-lead', Record: `${j.lead_id} (alert not sent)`, Outcome: 'failed', Error: String(j.send_error || j.send_status || 'not sent').slice(0, 500), At: Math.floor(Date.now() / 1000) } } }; });

// A send that Meta rejected or W12 found invalid (unknown template, empty variable, no key...) is logged: it used to vanish and be retried every run.
// "blocked" (allowlist, quiet hours, ledger unreachable) is normal and stays silent.
return $input.all().map((it) => { const j = it.json; return { json: { ...j, log: { Workflow: 'W5-reminders', Record: `${j.booking_uid} (${j.kind}) not sent`, Outcome: 'failed', Error: String(j.send_error || j.send_status || 'not sent').slice(0, 500), At: Math.floor(Date.now() / 1000) } } }; });

// A send that Meta rejected or W12 found invalid (unknown template, empty variable, no key...) is logged: it used to vanish and be retried every run.
// "blocked" (allowlist, quiet hours, ledger unreachable) is normal and stays silent.
return $input.all().map((it) => { const j = it.json; return { json: { ...j, log: { Workflow: 'W6-followups', Record: j.kind === 'rebook' ? `${j.booking_uid} (rebook) ${j.lead_id} not sent` : `${j.lead_id} (followup) not sent`, Outcome: 'failed', Error: String(j.send_error || j.send_status || 'not sent').slice(0, 500), At: Math.floor(Date.now() / 1000) } } }; });

// One item per delivery receipt (the message branch drops them: it only reads events[]).
const out = [];
$input.all().forEach((item, i) => {
  const { events, rejected, statuses_seen, http_status, response_body, reject_reason, kind, status_events, ...c } = item.json;
  for (const ev of status_events || []) out.push({ json: { ...c, ...ev }, pairedItem: { item: i } });
});
return out;

// phone_number_id -> clinic (same rule as W2 – Resolve Clinic)
const rows = (i) => (Array.isArray($input.all()[i].json.records) ? $input.all()[i].json.records : []);
return $input.all().map((it, i) => {
  const ctx = $('W2 – Split Statuses').all()[i].json;
  const want = String(ctx.phone_number_id || '').trim();
  const rec = rows(i).find((r) => r && r.fields && String(r.fields.WA_Phone_Number_ID === undefined || r.fields.WA_Phone_Number_ID === null ? '' : r.fields.WA_Phone_Number_ID).trim() === want);
  const f = rec ? rec.fields : {};
  const ok = !!want && !!rec && String(f.Active).toUpperCase() === 'TRUE' && !!String(f.Grist_Doc_ID || '').trim();
  return { json: { ...ctx, clinic_found: ok, doc_id: ok ? String(f.Grist_Doc_ID).trim() : '' }, pairedItem: { item: i } };
});

// Delivery receipt -> what to change. Statuses only move FORWARD (queued < sent < delivered < read); "failed" can only follow a message that was not
// delivered yet; the same receipt twice changes nothing. Unreadable Grist answers change nothing (Meta repeats receipts).
const rank = { sending: 0, uncertain: 0, unconfirmed: 0, accepted: 1, sent: 1, delivered: 2, read: 3 };
const mrank = { queued: 0, sent: 1, delivered: 2, read: 3 };
return $input.all().map((it, i) => {
  const ev = $('W2 – Status Resolve Clinic').all()[i].json;
  const led = $('W2 – Status Ledger').all()[i].json;
  const msg = it.json;
  const now = Math.floor(Date.now() / 1000);
  let ledger_patch = null, message_patch = null, log_failed = null, outcome = 'ignored';
  const lrows = Array.isArray(led.records) ? led.records.filter((r) => !['rejected', 'duplicate'].includes(String((r.fields || {}).Status || ''))) : [];
  const lr = lrows[0];
  if (lr) {
    const cur = String(lr.fields.Status || '');
    const want = ev.status === 'sent' ? 'accepted' : ev.status;          // Meta "sent" = accepted by WhatsApp: the ledger already says accepted
    const fields = {};
    if (ev.status === 'failed') { if (rank[cur] !== undefined && rank[cur] <= 1) { fields.Status = 'failed'; fields.Error = `${ev.error_code || ''} ${ev.error_text || 'delivery failed'}`.trim().slice(0, 300); fields.Error_Code = ev.error_code || 0; } }
    else if ((rank[want] || 0) > (rank[cur] === undefined ? -1 : rank[cur])) fields.Status = want;
    if (!String(lr.fields.WA_Message_ID || '') && ev.wa_message_id) fields.WA_Message_ID = ev.wa_message_id;
    if (fields.Status || fields.WA_Message_ID) { fields.Updated_At = now; ledger_patch = { records: [{ id: lr.id, fields }] }; outcome = fields.Status || 'linked'; }
  }
  const mr = Array.isArray(msg.records) ? msg.records.find((r) => (r.fields || {}).Direction === 'Out') : null;
  if (mr) {
    const cur = String(mr.fields.Status || 'queued');
    if (ev.status === 'failed') { if (mrank[cur] !== undefined && mrank[cur] <= 1) { message_patch = { records: [{ id: mr.id, fields: { Status: 'failed' } }] }; outcome = 'failed'; } }
    else if ((mrank[ev.status] || 0) > (mrank[cur] === undefined ? -1 : mrank[cur])) { message_patch = { records: [{ id: mr.id, fields: { Status: ev.status } }] }; if (outcome === 'ignored') outcome = ev.status; }
  }
  if (ev.status === 'failed' && (ledger_patch || message_patch)) log_failed = { Workflow: 'W2-delivery-status', Record: `${(lr && lr.fields.Idem_Key) || ev.wa_message_id} (delivery failed)`.slice(0, 200), Outcome: 'failed', Error: `${ev.error_code || ''} ${ev.error_text || 'delivery failed'}`.trim().slice(0, 500), At: now };
  return { json: { ...ev, ledger_patch, message_patch, log_failed, status_outcome: outcome }, pairedItem: { item: i } };
});

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

// E.164 phone normaliser pasted into every Code node that handles a phone number (replaces the +91-only function; the function name is kept so that
// every call site stays as it was). Accepts: +<country><number>, 00<country><number>, and numbers written locally for the DEFAULT country
// (FLOWHQ_DEFAULT_COUNTRY_CODE, default 91 = India: 10-digit mobile starting 6-9, optional leading 0 or 91). Result: +<digits> (8-15 digits) or null.
// It checks the SHAPE only. Whether a number can receive WhatsApp is up to Meta (error 131026 etc.), whether we may write to it up to W12.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  const s = String(raw).trim();
  const cc = (typeof $env !== 'undefined' && $env && /^[1-9]\d{0,2}$/.test(String($env.FLOWHQ_DEFAULT_COUNTRY_CODE || ''))) ? String($env.FLOWHQ_DEFAULT_COUNTRY_CODE) : '91';
  let digits = s.replace(/\D/g, '');
  if (s.startsWith('00')) digits = digits.slice(2);
  else if (!s.startsWith('+')) {                                  // written locally
    if (cc === '91') { if (!(digits.length === 12 && digits.startsWith('91'))) { if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1); digits = `91${digits}`; } }
    else digits = `${cc}${digits.replace(/^0+/, '')}`;
  }
  let valid = /^[1-9]\d{7,14}$/.test(digits);
  if (valid && digits.startsWith('91')) valid = /^91[6-9]\d{9}$/.test(digits);   // +91 numbers are Indian mobiles
  return { phone: valid ? `+${digits}` : null, valid };
}

// W1 STAFF ALERT (replaces the stub). Who is told: the clinic owner (Settings > owner_phone), or TEST_PHONE while TEST_MODE is on (a missing TEST_MODE row counts as ON).
// Same send guard as W3: quiet hours 21:00-08:00 IST hold the alert (W3 escalates a lead nobody answered). W12 sends: approved template, idempotency key, ledger.
const from = (name) => {
  try { return $(name).first().json; } catch (e) { return null; }   // throws if that branch did not run
};
const ctx = from('W1 – Build update') || from('W1 – Build new lead');
const settings = {};
for (const r of Array.isArray($json.records) ? $json.records : []) { const f = r.fields || {}; if (f.Key) settings[String(f.Key).trim()] = f.Value; }
const owner = normalizeIndianPhone(settings.owner_phone).phone;
const testPhone = normalizeIndianPhone(settings.TEST_PHONE).phone;
const decision = decideSend({ kind: 'transactional', flag_value: null, opted_out: false, automation_paused: false, patient_phone: owner, test_mode: settings.TEST_MODE, test_phone: testPhone, now_ms: Date.now() });
const hash = (s) => { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0; return h.toString(36); };
const clinic = ctx.clinic_name || ctx.clinic_slug;
const enquiry = String(ctx.enquiry || '').replace(/\s+/g, ' ').trim().slice(0, 200);
const what = ctx.action === 'created' ? 'New website lead' : 'Existing lead enquired again';
return {
  json: {
    ...ctx,
    source_workflow: 'W1-website-lead',
    audience: 'staff',
    template: 'new_lead_staff_alert',
    template_params: { clinic_name: clinic, lead_name: ctx.name, lead_phone: ctx.phone, enquiry: ctx.action === 'created' ? enquiry : `(again) ${enquiry}`.trim() },
    message_text: `${what} (${clinic}): ${ctx.name}, ${ctx.phone}${enquiry ? ` - "${enquiry}"` : ''}. ${ctx.lead_id}.`,
    idem_key: `W1:${ctx.action}:${ctx.lead_id}:${hash(enquiry)}`,   // a retried submission never alerts twice
    wa_phone_number_id: ctx.wa_phone_number_id,
    lead_phone: ctx.phone,
    decision,
    send: decision.send,
    settings_ok: Array.isArray($json.records),
  },
};

// The lead is stored (the website already got its answer). What happened to the staff alert is logged honestly.
const j = $json;
const note = j.sent === true ? '' : (j.duplicate === true ? 'staff alert already sent earlier (duplicate)' : (j.uncertain === true ? `lead stored; staff alert uncertain: ${j.send_error || 'no clear answer from Meta'} (not sent again)` : `lead stored; staff alert not sent: ${j.send_error || j.send_status || 'unknown'}`));
return { json: { ...j, staff_alert_sent: j.sent === true, log: { Workflow: 'W1-website-lead', Record: `${j.lead_id} (${j.action})`, Outcome: j.sent === true ? 'ok' : (j.duplicate === true ? 'ok' : (['rejected', 'invalid'].includes(j.send_status) || j.uncertain === true ? 'failed' : 'ok')), Error: note.slice(0, 500), At: Math.floor(Date.now() / 1000) } } };

// The lead is stored; the alert was held by the guard (quiet hours, no owner number, TEST_MODE without TEST_PHONE ...). W3 escalates a lead nobody answers.
const j = $json;
return { json: { ...j, staff_alert_sent: false, log: { Workflow: 'W1-website-lead', Record: `${j.lead_id} (${j.action})`, Outcome: 'ok', Error: `lead stored; staff alert not sent now: ${(j.decision && j.decision.reason) || 'guard'}${j.settings_ok ? '' : ' (clinic Settings could not be read)'}`.slice(0, 500), At: Math.floor(Date.now() / 1000) } } };

// Every Grist write succeeded (a failed write stops the run: the webhook then answers 500 and Cal.com / a person can retry).
// confirm = a booking was created or moved AND the send guard allows a confirmation now.
const from = (name) => {
  try { return $(name).first().json; } catch (e) { return null; }   // throws if that branch did not run
};
const made = from('W4 – Plan writes');
const planned = made || from('W4 – Plan appointment');
const action = planned && planned.plan ? planned.plan.action : 'skip';
const confirm = !!made && ['create', 'update'].includes(action) && !!made.confirmation && made.confirmation.decision && made.confirmation.decision.send === true;
return { json: { action, confirm, uid: planned ? planned.uid : '' } };

// The booking confirmation for W12 (approved template booking_confirmation). Recipient and permission come from the guard in W4 – Plan writes.
const p = $('W4 – Plan writes').first().json;
const c = p.confirmation;
const wrote = $('W4 – Grist write').all();
const expanded = $('W4 – Expand writes').all();
let appt_row_id = 0;                                  // the appointment row this confirmation is about (new row id, or the one that was updated)
expanded.forEach((e, i) => {
  if (e.json.table !== 'Appointments') return;
  const recs = ((wrote[i] || {}).json || {}).records;
  if (e.json.method === 'POST' && recs && recs[0]) appt_row_id = Number(recs[0].id) || appt_row_id;
  if (e.json.method === 'PATCH' && e.json.body.records[0].fields.Status === 'Booked') appt_row_id = e.json.body.records[0].id;
});
return { json: {
  source_workflow: 'W4-booking-sync', audience: 'patient', idem_key: `W4:booking_confirmation:${p.uid}:${p.start}`,   // one confirmation per booking and time
  template: c.template, template_params: c.template_params, message_text: c.message_text, decision: c.decision,
  wa_phone_number_id: p.wa_phone_number_id, grist_base_url: p.grist_base_url, doc_id: p.doc_id, lead_row_id: c.lead_row_id, lead_phone: c.lead_phone,
  appt_row_id, booking_uid: p.uid, start: p.start, lead_label: p.lead_label,
} };

// What happened to the confirmation. Confirm_Sent is set when W12 handled it (sent, uncertain or duplicate), so it is never sent twice.
const j = $json;
const handled = j.sent === true || j.uncertain === true || j.duplicate === true;
const outcome = j.sent === true ? 'ok' : (j.duplicate === true ? 'skipped' : (j.uncertain === true || ['rejected', 'invalid'].includes(j.send_status) ? 'failed' : 'skipped'));
const error = j.sent === true ? '' : (j.uncertain === true ? `uncertain: ${j.send_error || 'no clear answer from Meta'} (not sent again)` : String(j.send_error || j.send_status || 'not sent'));
return { json: { ...j, confirm_patch: handled && Number(j.appt_row_id) > 0 ? { records: [{ id: Number(j.appt_row_id), fields: { Confirm_Sent: Math.floor(Date.now() / 1000) } }] } : null, log: { Workflow: 'W4-booking-sync', Record: `${j.booking_uid} (confirmation) ${j.lead_label || ''}`.trim().slice(0, 200), Outcome: outcome, Error: error.slice(0, 500), At: Math.floor(Date.now() / 1000) } } };

const p = $('W12 – Prepare request').first().json;

const stop = (why) => ({
  json: {
    ...p,
    early: {
      send_status: 'blocked',
      send_error: why,
      ledger_status: ''
    }
  }
});

// Fail closed if the consent requirement is missing or invalid.
if (p.prep?.needs_consent === undefined ||
    p.prep?.needs_consent === null) {
  return stop('consent check: needs_consent flag is missing; nothing was sent');
}

// Consent is not required for this message.
// Continue to the ledger and normal send safeguards.
if (p.prep.needs_consent === false) {
  return {
    json: {
      ...p,
      consent_ok: true,
      consent_skipped: true
    }
  };
}

// Consent IS required from this point onward.
if (!p.prep.consent_phone) {
  return stop(
    'consent check: the lead phone number is missing or invalid; nothing was sent'
  );
}

if (!Array.isArray($json.records)) {
  return stop(
    `consent check: could not read the lead in Grist (${
      String(($json.error &&
        ($json.error.message || $json.error)) || 'no answer')
        .replace(/\s+/g, ' ')
        .slice(0, 150)
    }); nothing was sent`
  );
}

const lead = $json.records.find((r) => r && r.fields);

if (!lead) {
  return stop(
    'consent check: no lead with this phone number in LEADS; nothing was sent'
  );
}

if (lead.fields.Opted_Out === true) {
  return stop('the lead has opted out; nothing was sent');
}

if (lead.fields.Consent_WhatsApp !== true) {
  return stop(
    'no WhatsApp consent on file for this lead (LEADS.Consent_WhatsApp); a business-initiated template was not sent'
  );
}

return {
  json: {
    ...p,
    consent_ok: true,
    consent_skipped: false
  }
};

// E-mail for the clinic (always when FLOWHQ_ALERT_EMAIL_TO is set) and, if switched on, an acknowledgement for the person. Plain text, no tracking.
const j = $json;
const cfg = $('W1 – Config').first().json;
const clean = (s, n) => String(s === null || s === undefined ? '' : s).replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
const clinic = clean(j.clinic_name || j.clinic_slug, 100);
const emails = [];
const to = String(cfg.alert_email_to || '').split(/[,;]+/).map((x) => x.trim()).filter(Boolean);
const first = (s) => clean(s, 60).split(' ')[0] || 'there';
if (to.length) {
  const what = j.action === 'created' ? 'New website lead' : 'Existing lead enquired again';
  emails.push({ kind: 'staff', email_to: to.join(', '), email_from: cfg.email_from, subject: `${what}: ${clean(j.name, 60)} (${clinic})`.slice(0, 200), body: [`${what} for ${clinic}`, '', `Name: ${clean(j.name, 100)}`, `Phone: ${clean(j.phone, 30)}`, j.email ? `E-mail: ${clean(j.email, 120)}` : '', `Lead: ${clean(j.lead_id, 40)}`, '', 'What they wrote:', clean(j.enquiry, 1000) || '(nothing)', '', 'WhatsApp alert: ' + (j.staff_alert_sent === true ? 'sent' : 'not sent (see Run_Log)')].filter((l, i, a) => l !== '' || (a[i - 1] !== '' && i > 0)).join('\n') });
}
const hour = new Date(Date.now() + 5.5 * 3600 * 1000).getUTCHours();
const quiet = hour >= 21 || hour < 8;
const testMode = !!(j.decision && j.decision.test_mode);
let patient_note = '';
if (cfg.email_patient_ack === true && j.action === 'created' && j.email) {
  if (j.consent_email !== true) patient_note = 'no e-mail consent';
  else if (testMode) patient_note = 'TEST_MODE: no e-mail to patients';
  else if (quiet) patient_note = 'quiet hours: no e-mail to patients now';
  else emails.push({ kind: 'patient', email_to: j.email, email_from: cfg.email_from, subject: `We received your enquiry - ${clinic}`.slice(0, 200), body: `Hello ${first(j.name)},\n\nThank you for contacting ${clinic}. We have received your enquiry and a member of the team will get back to you.\n\nThis is an automatic message. If you did not make this enquiry you can ignore it.\n` });
}
return { json: { ...j, emails, patient_note } };

// Fold the e-mail outcome into the Run_Log row. A failed e-mail never loses the lead. The run only counts as "failed" when NO alert reached the clinic (WhatsApp or e-mail).
const plan = $('W1 – Email plan').first().json;
const items = $input.all();
const sent = plan.emails.length && items.length === plan.emails.length && items.every((it) => it.json && (it.json.messageId !== undefined || it.json.accepted !== undefined || it.json.error !== undefined)) ? items : null;
const notes = [];
let staffMailOk = false;
if (sent) plan.emails.forEach((e, i) => {
  const err = sent[i].json.error;
  if (e.kind === 'staff') staffMailOk = !err;
  notes.push(err ? `${e.kind} e-mail failed: ${String(err.message || err).replace(/\s+/g, ' ').slice(0, 120)}` : `${e.kind} e-mail sent`);
});
if (plan.patient_note) notes.push(plan.patient_note);
const log = { ...plan.log };
if (notes.length) log.Error = [log.Error, ...notes].filter(Boolean).join(' | ').slice(0, 500);
if (plan.emails.some((e) => e.kind === 'staff') && !staffMailOk && plan.staff_alert_sent !== true) log.Outcome = 'failed';
const { emails, patient_note, ...rest } = plan;
return { json: { ...rest, log, staff_email_sent: staffMailOk } };

// W14 CONFIG GUARD (production hardening). Stops the run - before anything reads Grist, calls Meta or an AI provider -
// when a required setting is missing, still a placeholder, or unsafe. The message names the variable to set (never its value).
const cfg = $input.first().json || {};
const problems = [];
const blank = (v) => v === undefined || v === null || String(v).trim() === '' || /^(PASTE_|PH_|CHANGE_ME|REPLACE_ME)/i.test(String(v).trim());
const need = (key, env, min) => { const v = cfg[key]; if (blank(v)) problems.push(`${env} is not set`); else if (min && String(v).trim().length < min) problems.push(`${env} is too short (min ${min} characters)`); };
need('grist_base_url', 'FLOWHQ_GRIST_URL');
if (!blank(cfg.grist_base_url) && !/^https?:\/\/[^\s/]+/i.test(String(cfg.grist_base_url).trim())) problems.push('FLOWHQ_GRIST_URL must start with http:// or https://');
need('registry_doc_id', 'FLOWHQ_REGISTRY_DOC_ID');
if (problems.length) throw new Error(`FlowHQ configuration incomplete in W14: ${problems.join('; ')}. See DEPLOYMENT.md > Environment variables.`);
return $input.all();

const cfg = $('W14 – Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');

const clinics = ($input.first().json.records || []).filter(
  (r) =>
    r.fields &&
    String(r.fields.Active).toUpperCase() === 'TRUE' &&
    String(r.fields.Grist_Doc_ID || '').trim()
);

return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
    wa_phone_number_id: String(r.fields.WA_Phone_Number_ID || '').trim(),
  },
  pairedItem: { item: 0 },
}));

// W14 SEND-LEDGER RECONCILE. A ledger row stays "sending" when the run died (or Grist was down) after Meta was called; it stays "uncertain" when Meta gave no
// clear answer. Neither is ever re-sent. Here they are only MARKED so a person can look: sending older than stale_minutes -> uncertain; uncertain older than
// unconfirmed_hours (no delivery receipt arrived) -> unconfirmed. Each change is a failed Run_Log row (Workflow W14-send-ledger). A delivery receipt (W2)
// settles a row at any time and wins over this job.
const cfg = $('W14 – Config').first().json;
const clinics = $('W14 – Split clinics').all();
const now = Math.floor(Date.now() / 1000);
const staleSec = (Number(cfg.stale_minutes) || 15) * 60;
const longSec = (Number(cfg.unconfirmed_hours) || 24) * 3600;
return $input.all().map((it, i) => {
  const clinic = clinics[i].json;
  const patches = [];
  const logs = [];
  for (const r of Array.isArray(it.json.records) ? it.json.records : []) {
    const f = r.fields || {};
    const age = now - (Number(f.Updated_At) || Number(f.Created_At) || now);
    if (f.Status === 'sending' && age >= staleSec) {
      patches.push({ id: r.id, fields: { Status: 'uncertain', Error: 'no result was recorded (the run may have stopped after calling Meta); not sent again', Updated_At: now } });
      logs.push({ Workflow: 'W14-send-ledger', Record: `${f.Idem_Key} (sending -> uncertain)`.slice(0, 200), Outcome: 'failed', Error: 'no result recorded after the send was claimed; check WhatsApp Manager; it will not be sent again', At: now });
    } else if (f.Status === 'uncertain' && age >= longSec) {
      patches.push({ id: r.id, fields: { Status: 'unconfirmed', Updated_At: now } });
      logs.push({ Workflow: 'W14-send-ledger', Record: `${f.Idem_Key} (uncertain -> unconfirmed)`.slice(0, 200), Outcome: 'failed', Error: `no delivery receipt within ${cfg.unconfirmed_hours} h; it is unknown whether the message arrived; it will not be sent again`, At: now });
    }
  }
  return { json: { ...clinic, has_changes: patches.length > 0, patch: { records: patches.slice(0, 100) }, logs: { records: logs.slice(0, 100).map((fields) => ({ fields })) } }, pairedItem: { item: i } };
});

// Race guard (website integration). Two enquiries for the same phone can arrive at the same moment (two executions) and both create a lead.
// After creating, read the leads with this phone again: the LOWEST row id is the lead. If our row is not it, another run got there first.
const ctx = $('W1 – Build new lead').first().json;
const made = $('W1 – Create lead').first().json;
const madeId = made && Array.isArray(made.records) && made.records[0] ? Number(made.records[0].id) : 0;
const rows = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && Number.isInteger(r.id) && r.fields).sort((a, b) => a.id - b.id);
const canon = rows[0] || null;                                   // null when the re-read failed: carry on exactly as before
const race = !!canon && madeId > 0 && canon.id !== madeId;
return [{ json: { ...ctx, race, made_row_id: madeId, kept_row_id: canon ? canon.id : madeId, skip_reason: race ? 'parallel submission: lead row ' + canon.id + ' was created first and is kept' : '' } }];

// What the race branch tells staff: which row was kept and whether the extra row could be removed.
const g = $('W1 – Race guard').first().json;
const removed = !($json && $json.error);   // Grist answers a delete with null: only an error item means it failed
return [{ json: { ...g, skip_reason: g.skip_reason + (removed ? '; the duplicate row ' + g.made_row_id + ' was removed' : '; the duplicate row ' + g.made_row_id + ' could NOT be removed automatically: please delete it in Grist') } }];
